2024년 1월3일 갈라디아서 1장 11절~24절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 유대교(13,14절), 사도(17,19절), 
4.주제만들기: 무엇보다 중요한 것은 복음
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 바울은 복음은 그리스도로 말미암는 다는 것을 강조한다.
- 바울은 자신이 유대교였으며 누구보다 지나치게 유대교를 믿었다고 말한다.
- 바울은 자신이 하나님의 은혜로 믿음 갖게 되었다고 말한다.
- 바울은 베드로와 야고보 외에는 사도들을 만나지 못했으나 자신의 변화 된 삶은 소문을 통해서 알 수 있을 것이라 말한다.
7.하나님 찾기 (해석) 
8.인간(해석):- 당시 갈라디아 교회도 성도들이 여러 문제에 있었던 것 같다. 돌봐야할 영혼은 많은데 선교와 사역은 이어져 가야하니 바울이 얼마나 답답했을지 생각해본다. 갈라디아 교회 성도들이 잘못된 복음에 흔들리고, 자신의 사도권을 의심할 때 자괴감까지 들었을 것이다. 그럼에도 불구하고 편지로 차분히 자신의 생각을 담담히 적은 바울이 대단하게 느껴진다. 
- 바울은 자신이 유대교를 지나치게 믿었다고 말했다. 그렇기 때문에 바울은 흔들리는 성도의 마음을 이해했을 수도 있다. 자신의 경험을 토대로 진짜 복음이 무엇인지 알려주는 바울의 심정이 어땠을지 생각해본다. 
9. 적용(나): 
- 가끔 나도 믿음이 연약해질 때 스스로 부끄러울 때가 있다. 믿음이 연약해진다는 것은 말씀과 기도가 적었다는 것을 의미한다. 말씀과 기도를 꾸준히 이어가야겠다. 
- 바울처럼 흔들리지 않는 믿음을 갖기 위해선 성령님과 동행함을 매일 느끼며 살아야한다. 자신을 더 단련시켜야겠다.
- 복음을 잘못 믿고 있는 사람들을 위해 기도해야겠다.
10. 영적터치(단어/구절)
- 14절 지나치게 믿어
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-12-22', '갈라디아서', '2장 1절 ~ 10절', '제목 없음', '(갈라디아서 2장)
1.  십사 년 후에 내가 바나바와 함께 디도를 데리고 다시 예루살렘에 올라갔나니
2. 계시를 따라 올라가 내가 이방 가운데서 전파하는 복음을 그들에게 제시하되 유력한 자들에게 사사로이 한 것은 내가 달음질하는 것이나 달음질한 것이 헛되지 않게 하려 함이라
3. 그러나 나와 함께 있는 헬라인 디도까지도 억지로 할례를 받게 하지 아니하였으니
4. 이는 가만히 들어온 거짓 형제들 때문이라 그들이 가만히 들어온 것은 그리스도 예수 안에서 우리가 가진 자유를 엿보고 우리를 종으로 삼고자 함이로되
5. 그들에게 우리가 한시도 복종하지 아니하였으니 이는 복음의 진리가 항상 너희 가운데 있게 하려 함이라
6. 유력하다는 이들 중에 (본래 어떤 이들이든지 내게 상관이 없으며 하나님은 사람을 외모로 취하지 아니하시나니) 저 유력한 이들은 내게 의무를 더하여 준 것이 없고
7. 도리어 그들은 내가 무할례자에게 복음 전함을 맡은 것이 베드로가 할례자에게 맡음과 같은 것을 보았고
8. 베드로에게 역사하사 그를 할례자의 사도로 삼으신 이가 또한 내게 역사하사 나를 이방인의 사도로 삼으셨느니라
9. 또 기둥 같이 여기는 야고보와 게바와 요한도 내게 주신 은혜를 알므로 나와 바나바에게 친교의 악수를 하였으니 우리는 이방인에게로, 그들은 할례자에게로 가게 하려 함이라
10. 다만 우리에게 가난한 자들을 기억하도록 부탁하였으니 이것은 나도 본래부터 힘써 행하여 왔노라

