2023년 1월3일 갈라디아서 2장1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어(같은의미 단어)
할례: 3절 8절 9절
복음: 2절 5절 7절
유력: 6절(2)
이방인:2절 8절 9절
삼으셨느니라/가게하려 함이라/행하여 왔노라: 8절 9절 10절

4. 주제 만들기 
이방인을 향한 바울의 비전

5.하나님 찾기(관찰)
사람을 외모로 취하지 아니하시는 하나님
6.인간 찾기(관찰)
이방선교에 확고한 비전을 갖고있는 바울

7.하나님 찾기 (해석)

8. 인간 찾기 (해석)
바울은 복음에 대한 내용뿐만 아니라 복음에 대한 역활의 기준점을 명확히 알고있음을 볼수있다. 그가 기둥같이 여기는 베드로 야고보 요한으로부터 자신은 이방선교의 부르심을 받은 사명자임을 인정을 받았다. 즉 할례를 받은 유대인뿐만 아니라 받지않은 이방인 들을 대상으로 부름을 받은것을 명확히 하였다. 과거의 율법적 전통적으로만 여기는 틀에서 벗어나 오직 순수한 복음의 자유를 갖는 바울의 확고한 신앙을 어떠한 유력자들도 막을수가 없음을 볼수있다. 바울은 더 나아가 제자요 헬라인 디도에게 조차도 할례를 받지 않도록 결정하였다. 그가 이러한 담대함을 행할 수 있었던 것은 분명한 비전이 있었기 때문에 가능했던 것으로 보여진다. 8절에 보면 "베드로에게 역사하사 그를 할례자의 사도로 삼으신 이가 또한 내게 역사하사 나를 이방인의 사도로 삼으셨느니라" 사도들 마다 주시는 비전이 다름을 분명히 알수있다.

9. 적용(나)
올해 1월1일 꿈에 주님께서 이미 보여주신 국내거주하고 있는 동남아시아 권 외국인 청년들에게 복음을 전파할 비전을 분명히 보여주셨다. 우리 NKFC 에게 주신 비전을 붙잡고 담대히 나아가야겠다.

10. 영적 터치(단어/구절)
8절: 삼으신 이가 또한

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-12-23', '갈라디아서', '2장 11절 ~ 21절', '오직 예수', '갈라디아서 2장
11   게바가 안디옥에 이르렀을 때에 책망 받을 일이 있기로 내가 그를 대면하여 책망하였노라
12   야고보에게서 온 어떤 이들이 이르기 전에 게바가 이방인과 함께 먹다가 그들이 오매 그가 할례자들을 두려워하여 떠나 물러가매
13   남은 유대인들도 그와 같이 외식하므로 바나바도 그들의 외식에 유혹되었느니라
14   그러므로 나는 그들이 복음의 진리를 따라 바르게 행하지 아니함을 보고 모든 자 앞에서 게바에게 이르되 네가 유대인으로서 이방인을 따르고 유대인답게 살지 아니하면서 어찌하여 억지로 이방인을 유대인답게 살게 하려느냐 하였노라
15   우리는 본래 유대인이요 이방 죄인이 아니로되
16   사람이 의롭게 되는 것은 율법의 행위로 말미암음이 아니요 오직 예수 그리스도를 믿음으로 말미암는 줄 알므로 우리도 그리스도 예수를 믿나니 이는 우리가 율법의 행위로써가 아니고 그리스도를 믿음으로써 의롭다 함을 얻으려 함이라 율법의 행위로써는 의롭다 함을 얻을 육체가 없느니라
17   만일 우리가 그리스도 안에서 의롭게 되려 하다가 죄인으로 드러나면 그리스도께서 죄를 짓게 하는 자냐 결코 그럴 수 없느니라
18   만일 내가 헐었던 것을 다시 세우면 내가 나를 범법한 자로 만드는 것이라
19   내가 율법으로 말미암아 율법에 대하여 죽었나니 이는 하나님에 대하여 살려 함이라
20   내가 그리스도와 함께 십자가에 못 박혔나니 그런즉 이제는 내가 사는 것이 아니요 오직 내 안에 그리스도께서 사시는 것이라 이제 내가 육체 가운데 사는 것은 나를 사랑하사 나를 위하여 자기 자신을 버리신 하나님의 아들을 믿는 믿음 안에서 사는 것이라
21   내가 하나님의 은혜를 폐하지 아니하노니 만일 의롭게 되는 것이 율법으로 말미암으면 그리스도께서 헛되이 죽으셨느니라

