2024년 1월 4일 갈라디아서 2장 11~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
게바: 11, 12, 14 
외식: 13(2)
이방인: 12, 14(2)
유대인: 13, 14(2), 15
율법: 16(3), 19,
믿음: 16(2)
의롭다(의롭게): 16(3)
예수(그리스도): 16(3), 17(2), 20(2), 21
하나님: 19, 20, 21

4.주제 만들기: 오직 예수

5.하나님 찾기 (관찰)
- 

6.인간 찾기 (관찰)
- 이방인과 식사 교제 중에 유대인이 오는 것을 알고 자리를 피한 베드로
- 함께 자리를 피한 바나바
- 외식하는 베드로를 책망하는 바울
- 율법으로서가 아니라 그리스도를 믿는 믿음으로써 의롭게 됨을 말하는 바울

7.하나님 찾기 (해석) 

8.인간(해석): 
- 이방인에게도 구원함과 성령 세례가 임하는 것을 체험한 베드로가 야고보의 무리가 온다는 소식을 듣고 식사 자리에서 떠났다.
- 아마도 할례를 받아야만 한다고 주장하는 유대주의자들과 성향이 매우 강한 야고보에게 책망받을 것이 두려워 자리를 피한 것으로 유추된다. 
- 베드로가 유대주의자와의 괜한 싸움이 일어나는 것을 피하려고 자리를 떠난 것일 수도 있지만, 바울이 책망한 것을 봐서는 전자로 유추하는 것이 합리적인 것 같다.
- 교회가 기둥같이 여기는 베드로가 자리를 피하자 바나바도 함께 자리를 피함
- 지도자가 실수하면 초신자인 이방인 뿐만 아니라 바나바 같은 대단한 믿음의 사람도 끌려갈 수 있다.
- 이방인의 사도로 예수님께 부름을 받은 바울은 이방인의 구원에 유대주의자들이 주장하는 할례는 아무 능력이 없음을 강하게 주장한 것이다. 
- 그래서 의롭다 함은 오직 그리스도를 믿는 믿음으로 얻는 것이라 정확하게 말하고 있다. 이것이 바울 신학의 핵심이라고 할 수 있는 이신칭의이다.
- 나아가 율법주의자였던 자신이 이제는 율법이 아니라 오직 예수 그리스도를 믿는 믿음 안에서 살고 있다고 고백한다.

9. 적용(나): 
- 나를 바라보는 형제 자매님들이 있다. ‘오직 의인은 믿음으로 말미암아 살리라’라는 진리를 형제 자매님들에게 정확히 가르쳐야 한다. 나 또한 이 믿음으로만 살아가야 한다.
- 내가 율법주의자가 되면 나와 함께 하는 이들도 함께 율법주의자가 될 수 있다. 한마디 말을 하더라도 하나님의 말씀을 전하는 것 같이 조심해야 한다.

10. 영적터치(단어/구절)  
  19   내가 율법으로 말미암아 율법에 대하여 죽었나니 이는 하나님에 대하여 살려 함이라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-12-24', '갈라디아서', '3장 1절 ~ 10절', '율법의 행위보다 중요한 것은 예수님의 십자가를 믿는 믿음', '[갈3:1-10]
1 어리석도다 갈라디아 사람들아 예수 그리스도께서 십자가에 못 박히신 것이 너희 눈 앞에 밝히 보이거늘 누가 너희를 꾀더냐
2 내가 너희에게서 다만 이것을 알려 하노니 너희가 성령을 받은 것이 율법의 행위로냐 혹은 듣고 믿음으로냐
3 너희가 이같이 어리석으냐 성령으로 시작하였다가 이제는 육체로 마치겠느냐
4 너희가 이같이 많은 괴로움을 헛되이 받았느냐 과연 헛되냐
5 너희에게 성령을 주시고 너희 가운데서 능력을 행하시는 이의 일이 율법의 행위에서냐 혹은 듣고 믿음에서냐
6 아브라함이 하나님을 믿으매 그것을 그에게 의로 정하셨다 함과 같으니라
7 그런즉 믿음으로 말미암은 자들은 아브라함의 자손인 줄 알지어다
8 또 하나님이 이방을 믿음으로 말미암아 의로 정하실 것을 성경이 미리 알고 먼저 아브라함에게 복음을 전하되 모든 이방인이 너로 말미암아 복을 받으리라 하였느니라
9 그러므로 믿음으로 말미암은 자는 믿음이 있는 아브라함과 함께 복을 받느니라
10 무릇 율법 행위에 속한 자들은 저주 아래에 있나니 기록된 바 누구든지 율법 책에 기록된 대로 모든 일을 항상 행하지 아니하는 자는 저주 아래에 있는 자라 하였음이라

