2024년 1월6일 갈라디아서 3장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 율법의 행위(2,5절), 믿음(2,5,6,7,8,9절), 성령(2,3,5절), 이방(8,9절), 아브라함(6,7,9절)
4.주제만들기: 율법의 행위보다 중요한 것은 예수님의 십자가를 믿는 믿음
5.하나님 찾기(관찰)
6.인간 찾기(관찰)
- 갈라디아 교회 성도들은 율법주의와 신앙과 구원에 대해 잘못된 해석으로 어려움을 겪고 있다. 
- 바울은 율법과 믿음의 차이에 대해 안내하고, 아브라함의 예를 들어 믿음을 강조한다. 또한 이방인들이 구원을 받는 것은 미리 에언된 일이었다고 말한다.
7.하나님 찾기(해석) 
8.인간(해석):
- 바울은 갈라디아 교회에서 겪고 있는 어려움을 안타까워하며 믿음에 대해 설명한다. 갈라디아교회는 예수님을 분명히 알고 있음에도 율법의 행위를 중요시하는 옛 신앙관으로 되돌아가는 모습을 보인다. 갈라디아 교회는 하나님을 열정적으로 믿었던 것 같다. 하지만 열정적인 마음이 교회 안에서 자신을 드러내기 위해 율법의 행위를 쫓은 것으로 보인다.   
9. 적용(나): 
- 갈라디아 교회에 보낸 바울의 편지를 통해 많은 것을 느낄 수 있다. 하나님을 사랑했던 열정이 잘못되면 율법주의로 빠질 수 있기에 자신의 신앙을 철저기 자기 검증을 해야한다. 또한 리더의 역할이 중요한데 바울이 떠나고 난 후 갈라디아 교회 안에 여러문제가 발생한 것을 보면 리더의 부재와 무능함은 교회를 어렵게 할 수 있다는 것을 느낀다. 
- 하나님을 생각하며 열정적이었던 마음이 식어있음을 느낀다. 나 스스로 엄청 위태로운 상황이라는 것을 깨닫는다. 하나님을 사랑하는 마음이 생각이 아닌 행동으로 이어지도록 기초부터 지켜나가야겠다.
- 나를 이끌어주는 영적 리더들에게 감사하다. 조재필 목사님, 박해민 전도사님, 강남비전교회 한재욱 목사님 이하 여러 사역자 분들게 감사하다. 리더들의 영육강건함을 위해 기도해야겠다.   
10. 영적터치(단어/구절): 율법의 행위
11. 믿음과 회개 및 감사기도로 마무리', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-12-25', '갈라디아서', '3장 11절 ~ 20절', '제목 없음', '(갈라디아서 3장)
11. 또 하나님 앞에서 아무도 율법으로 말미암아 의롭게 되지 못할 것이 분명하니 이는 의인은 믿음으로 살리라 하였음이라
12. 율법은 믿음에서 난 것이 아니니 율법을 행하는 자는 그 가운데서 살리라 하였느니라
13. 그리스도께서 우리를 위하여 저주를 받은 바 되사 율법의 저주에서 우리를 속량하셨으니 기록된 바 나무에 달린 자마다 저주 아래에 있는 자라 하였음이라
14. 이는 그리스도 예수 안에서 아브라함의 복이 이방인에게 미치게 하고 또 우리로 하여금 믿음으로 말미암아 성령의 약속을 받게 하려 함이라
15.  형제들아 내가 사람의 예대로 말하노니 사람의 언약이라도 정한 후에는 아무도 폐하거나 더하거나 하지 못하느니라
16. 이 약속들은 아브라함과 그 자손에게 말씀하신 것인데 여럿을 가리켜 그 자손들이라 하지 아니하시고 오직 한 사람을 가리켜 네 자손이라 하셨으니 곧 그리스도라
17. 내가 이것을 말하노니 하나님께서 미리 정하신 언약을 사백삼십 년 후에 생긴 율법이 폐기하지 못하고 그 약속을 헛되게 하지 못하리라
18. 만일 그 유업이 율법에서 난 것이면 약속에서 난 것이 아니리라 그러나 하나님이 약속으로 말미암아 아브라함에게 주신 것이라
19. 그런즉 율법은 무엇이냐 범법하므로 더하여진 것이라 천사들을 통하여 한 중보자의 손으로 베푸신 것인데 약속하신 자손이 오시기까지 있을 것이라
20. 그 중보자는 한 편만 위한 자가 아니나 하나님은 한 분이시니라

