바울은 신약의 구원의 핵심인 "이신칭의''를 11절에 명확하게 선포하였다. 구원은 율법을 통한 행위로 이루는 것이 아니라 오직고  예수를 믿는 믿음으로 이루어진다고 말하고 있다 오래전부터 이미 아브라함에게 약속을 하신 훗날 오실 그리스도를 드러내고 있다. 아담과 하와 가 본죄를 지은이후 하나님은 인간 스스로 해결할수 없는 죄를 율법을  뛰어넘는 약속 그리고 은혜로 믿음이란 통로로 사랑의 구원을 이루시는것을 바울은 나타내고 있다

