4. 주제 만들기 
율법을 벗어나 믿음으로 그리스도와 합해짐

5.하나님 찾기(관찰)
의를 행하시는 하나님
그리스도 와 합한자에게 그리스도 로 옷을 입혀주심
약속대로 유업을 이을수 있는 특권을 주시는 하나님 
6.인간 찾기 (관찰)
죄에 갇혀있는 모든 인간들
예수그리스도를 믿는자들이 받는 죄로부터의 자유와 주님과의 연합

7.하나님 찾기 (해석)

8. 인간 찾기 (해석)
행위나 율법으로 구원을 받지못지 못하는 이유로 ''모든 사람들은 죄에 갖혀사는 연약한 존재이기 때문'' 이 부분을 바울은 명확하게 나타냈다. 22절에 "성경이 모든 것을 죄 아래에 가두었으니" 기록되었다. 어떠한 선행으로도 참다운 구원에는 도달할수가 없음을 알수있다 온전한 주님과 합해지고 온전한 구원을 이루는 것은 오직 "믿음"밖에는 없다는 사실이다. 바울은 개인의 구원 뿐만아니라 믿음을 통하여 예수안에서 ''유대인이나 헬라인이나 종이나 자유인이나 남자나 여자나 다 그리스도 예수 안에서 하나이니라''
기록하였다. 즉 하나님은 모든 사람들을 차별없이 사랑하시고 기다시는 분임을 바울은 분명히 나타내고 있다.

9. 적용(나)
믿음을 더욱 갈구하며 믿음을 통한 받는 무궁한 주님의 은혜를 NKFC회원들이나 만나는 지체들에게 드러내고 나타내는데 더욱 힘을써야겠다.

