4.주제만들기: 바울의 호소
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 바울은 계속해서 갈라디아 교회에 호소한다.
- 바울은 갈라디아 교회 성도들에게 자신이 육체의 연약을 가지고 있었음에도 업신여기지 아니하고 복음을 받아들였음을 상기시킨다.
- 바울은 갈라디아 교회 성도들은 할 수만 있었다면 눈이라도 빼어 바울에게 줄 정도로 복음을 사모하고 열정이 넘쳤음을 말한다.
- 그러나 지금은 이간하는 자들에게 열심을 내려하여 바울이 참된 말을 하고 그리스도의 형상을 이루기 위해 다시 해산하는 마음으로 갈라디아 교회에 언성을 높인다고 말한다.
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울의 육체의 연약함은 눈이었을지 모른다.(정확하게 알지 못한 나의 추측) 갈라디아 교회 성도들은 바울이 육체의 연약함에도 불구하고 그를 사랑했고, 복음을 사랑했고, 열심을 다했다고 한다. 바울이 느끼기에 눈이라도 빼어 자신에게 줄 정도였다고 하니 그 사랑이 어느 정도였을지 어림짐작으로 알 수 있다. 
- 그러한 사랑도 사탄의 계략과 사탄에게 틈새를 내어주면 무너질 수 있음을 깨닫는다. 하나님을 처음 만나 깊은 사랑과 열정이 있었던 때처럼 영원할 것 같던 나의 마음이 하나님과 교제가 줄어들며 점점 소원해지고 세상 걱정과 근심에 사로잡혀 기도보다 세상일을 먼저 걱정하는 현재 나의 모습과도 같다.
9. 적용(나): 
- 바울의 호소는 예수님의 호소처럼 느껴진다. 오늘 하루 깨닫게 하신 주님께 감사하고, 당시 하나님을 열망했던 기억을 되새겨 보고자 한다. 
10. 영적터치(단어/구절) 
- 15절 눈이라도 빼어 나에게 주었으리라
11. 믿음과 회개 및 감사기도로 마무리
