바울은 아브라함의 복을 이어받아 하나님의 유업을 상속받은 자녀들에 대하여 나열하였다. 하나님 약속으로 말미암아 잉태하여 출산한 자녀들과 율법의 종 으로 태어난 두 종류를 대비시켰다. 아브라함의 여종 하갈을 통하여 출산된 종의 자녀  그리고 약속으로 태어난 이삭을 비교법으로 표현했다. 성령을 받고 태어난 자유의 자녀들은 더이상 죄의 속박가운데 있지 않고 유업을 받지만 성령을 받지않은 자들은 계속적으로 율법의 종의 상태에 놓여있다. 율법의 종 아래있는자들의 특징으로는 끊임없이 약속의 자녀들을 박해하고 있음을 바울은 지적하고 있다. 이 시대에도 마찬가지로 믿음을 붙잡고 사는 사람들을 향하여 사탄은 다양한 행위와 인간이 만들어놓은 잣대로 도전을 하고 있음을 알수있다

