7   너희가 달음질을 잘 하더니 누가 너희를 막아 진리를 순종하지 못하게 하더냐
8   그 권면은 너희를 부르신 이에게서 난 것이 아니니라
9   적은 누룩이 온 덩이에 퍼지느니라
10   나는 너희가 아무 다른 마음을 품지 아니할 줄을 주 안에서 확신하노라 그러나 너희를 
