- 할례와 율법을 지켜서 의롭다 함을 얻을 수 있는 사람이 없으니, 할례를 받으려 하지 말라
- 율법을 모두 지켜서 의롭다 함을 얻는 자는 사랑의 믿음이 없는 자로서 그리스도께 끊어지고 은혜에서 끊어진 자다.
- 우리는 성령님 안에서 그리스도를 믿음으로 말미암아 의롭다 하심을 받는 소망을 기다린다.  
- 우리를 구원하는 능력은 할례나 무할례에는 없고, 다만 예수 그리스도를 믿는 믿음밖에는 없다.
- 할례를 받아야 구원을 받는다는 권면은 하나님으로부터 나온 말이 아니라 너희를 교란하는 자에게 나온 말이다.
- 너희를 교란하는 자들은 심판을 받을 것이니, 너희는 그들의 말을 듣지 말고 은혜 안에 굳게 서서 은혜의 자유를 누려라.

9. 적용(나)
- 예수 그리스도를 믿는 믿음 안에서 구원의 소망을 바라며 즐거워하고, 이미 이루신 구원에 기뻐하며 주님의 사랑을 실천하며 살아야겠다.
- 할례도 무할례도 구원에는 아무런 효력이 없는데 초대교회 사람들이 갈등을 겪었던 것처럼 오늘날 형제 자매님들도 율법을 지켜야만 구원을 받는가에 대한 갈등이 있는 분들도 있을 것이다. 
- 성령 안에서 사랑의 믿음으로 말미암아 구원을 받는다는 자유를 누릴 수 있도록 우리를 자유롭게 하는 주 예수 그리스도를 바르게 전해야겠다.

10. 영적터치(단어/구절)  
  1   그리스도께서 우리를 자유롭게 하려고 자유를 주셨으니

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2023-12-31', '갈라디아서', '5장 11절 ~ 20절', '육체의 일에서 벗어나 성령이 이끄는 삶으로', '[갈5:11-20]
11 형제들아 내가 지금까지 할례를 전한다면 어찌하여 지금까지 박해를 받으리요 그리하였으면 십자가의 걸림돌이 제거되었으리니
12 너희를 어지럽게 하는 자들은 스스로 베어 버리기를 원하노라
13 형제들아 너희가 자유를 위하여 부르심을 입었으나 그러나 그 자유로 육체의 기회를 삼지 말고 오직 사랑으로 서로 종 노릇 하라
14 온 율법은 네 이웃 사랑하기를 네 자신 같이 하라 하신 한 말씀에서 이루어졌나니
15 만일 서로 물고 먹으면 피차 멸망할까 조심하라
16 내가 이르노니 너희는 성령을 따라 행하라 그리하면 육체의 욕심을 이루지 아니하리라
17 육체의 소욕은 성령을 거스르고 성령은 육체를 거스르나니 이 둘이 서로 대적함으로 너희가 원하는 것을 하지 못하게 하려 함이니라
18 너희가 만일 성령의 인도하시는 바가 되면 율법 아래에 있지 아니하리라
19 육체의 일은 분명하니 곧 음행과 더러운 것과 호색과
20 우상 숭배와 주술과 원수 맺는 것과 분쟁과 시기와 분냄과 당 짓는 것과 분열함과 이단과

