- 인간을 보호할 수 있는 성령도 주심
6.인간 찾기 (관찰)
- 바울은 자신이 율법주의자처럼 할례를 강조했다면 자신이 박해 받는 일도 없을 것이라 말한다.
- 바울은 인간이 받은 자유로 육체의 욕망을 위해 사용하지 말고 예수님께서 율법을 정리하신 것처럼 서로 사랑하는 일에 힘써야 한다고 말한다.
- 바울은 성령을 따라 인도하시는대로 행하면 율법과 육체의 욕망에 있지 않을 것이라 말한다. 
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울은 인간의 죄성에 대해 정확히 파악하고 있다. 예수님을 따라가는 삶, 성령이 이끄는 삶만 살아도 내 안에 있는 욕망과 죄들을 떨쳐버릴 수 있을텐데 그러지 못한 갈라디아 성도들에게 성령을 강조하며 육체의 욕망에서 벗어나도록 권면했다. 
9. 적용(나): 
- 내 안에 잘살고(좋은 집, 좋은 차, 좋은 환경, 자녀 교육, 물질의 풍요로움 등등) 싶은 마음이 나의 욕망일 수 있다. 하나님이 이끄시는 삶을 살도록 성령님의 인도하심을 따라 가야겠다. 
- 하나님께서 입을 여시고 기도하게 하심을 감사드린다. 주님과 교제의 시간을 하루의 모든 일 중 가장 기쁘고 설레이는 시간이 되길 소망한다. 
