8. 인간 찾기 (해석)
바울은 농사일을 비유로 믿는 성도들이 무엇을 심어야 되는지 가르치고 있다. 콩심으면 콩을 거두는 기본적인 자연의 법칙대로 육체를 위하여 심는자는 썩을것을 거두고 성령을 위하여 심는자는 영생을 거둘것을 확신하고 있다. 그럼 여기서 말하는 성령을 심는다 의 의미는 무엇일까?
답은 10절 이하에 명확하게 나와있다. "그러므로 우리는 기회 있는 대로 모든  이에게  착한 일을 하되" 로 기록되어 있다.
여기서 착한일이란 결국 상대를 위하는 일이고 성령의 열매 를 의미하는것임을 알수있다.
특별히 주목할것은 착한일을 하고 싶어도 하나님이 성도에게 기회를 허락 하셔야 됨을 바울은 인지하고  있다
