6.인간 찾기 (관찰)
- 할례를 받게 하려는 사람들. 이들은 자기들로 인해 할례받는 자가 생기는 것을 자랑으로 여김.
- 주 예수 그리스도의 십자가 밖에는, 자랑할 것이 아무것도 없다고 말하는 바울
- 할례를 받는 것이 중요한 것이 아니라, 거듭나는 것이 중요함을 주장하는 바울
- 예수의 흔적을 지니고 있다고 말하는 바울

7.하나님 찾기 (해석) 

8.인간(해석): 
- 율법주의자들은 자신들이 옳다함을 받기 위해 일함.
- 율법주의자들은 그리스도의 십자가로부터 오는 형벌을 면하고자 함. 
- 율법주의자들은 할례 받을 것을 주장하지만, 자신들도 율법을 지키지 못하고 있음.
- 그들은 할례자가 추가로 생기면 그것으로 자신들의 자랑거리를 삼으려고 하는 것.
(할례는 유대교와 기독교가 분리되는 결정적인 요인이 되었습니다.)
- 할례나 율법이 아니라, 주 예수 그리스도의 십자가로 인하여 구원을 받기 때문에 할례도 율법도 중요하지 않고, 그리스도를 믿는 믿음으로 새롭게 창조되는 것이 중요함.
- 오직 그리스도만 의지하면 됨.
- 바울은 예수님의 흔적을 지니고 있음. 이 흔적은 그리스도를 위하여 살아온 인생의 흔적으로 그리스도를 증언하며 겪은 굶주림과 헐벗음과 매맞음과 풍랑 등을 지나온 흔적이다.

9. 적용(나):
- 오늘날 교회에도 새로운 율법주의자들이 있다. 교회 안팎에서 만나는 사람들의 행위를 바라보며 정죄하는 자들인데, 특히 한국교회의 율법주의자들은 술과 담배에 민감하다. 
- 마음속의 온갖 더러운 죄, 보이지 않는 곳에서 행하는 죄들은 보지 않고 눈에 보이는, 아무것도 아닌 술과 담배를 하는 사람들을 정죄한다. 자기 나름의 틀을 정해놓고 자기가 안 하는 것 같은 죄(사실은 자기도 범하고 있는 경우가 많다)는 죄가 되고 자기가 하고 있는 것은 죄가 아닌 것이 된다. 
- 그 율법의 틀은 과연 누가 만든 것인가, 양심에 비추어 깊이 생각해 봐야 한다.
- 각자의 죄를 깨닫게 하시는 분은 오직 성령 하나님이시다. 우리는 우리의 죄를 알지 못한다. 그런데 감히 누가 사람을 판단하겠는가. 
- 판단을 하려면 그 사람이 예수님을 의지하는가, 세상을 의지하는가가 돼야 할 것이다.
- 물론 판단은 주님의 영역이다.

10. 영적터치(단어/구절)  
  15 오직 새로 지으심을 받는 것만이 중요하니라
