4.주제만들기: 하나님 안에서 하늘과 땅은 동일한 은혜와 영광을 누리는 곳이다. 
5.하나님 찾기 (관찰)
- 하늘의 신령한 복을 우리에게 주심
- 창세전부터 우리를 택하사 사랑안에서 거룩하고 흠이 없게 하시려고 예수 그리스도로 말미 암아 하나님의 아들들이 되게 하심
- 모든 것은 거져주신 것이고 은혜와 영광을 찬송하게 하려 하심
- 예수님을 통하여 우리의 죄를 속량하심
- 속량의 비밀을 우리에게 알리셨고 하늘에 있는 것이나 땅에 있는 것이나 그리스도 안에서 통일되게 하려 하심
6.인간 찾기 (관찰)
- 바울은 에베소 교회 성도들에게 문안하며 하나님의 구원 계획과 그리스도 예수 안에서의 복음, 하나님의 은혜에 대해 말하고 있다. 
7.하나님 찾기 (해석) 
- 하나님은 예수님을 통해 우리에게 은혜와 복을 더하여 주셨다. 예수님을 통해 우리의 죄를 지워버릴 수 있는 통로를 만들어주셨는데, 이는 하늘에서만 누릴 수 있었던 거룩함을 땅에서도 누릴 수 있게 하시는 하나님의 전적인 은혜이다. 
- 하나님은 창세 전부터 우리를 택하시고 사랑안에서 거룩하고 흠이 없게 하셨다. 하나님의 깊은 사랑은 예수님을 통해 보이셨고, 땅에서 하나님의 십자가 사랑을 느낄 수 있게 되었다.
8.인간(해석):
- 바울의 편지를 통해 에베소 교회와 현대에 살아가는 우리가 하늘과 땅이 차이가 없이 거룩한 곳임을 선포한다. 예수님의 사랑은 하늘을 위해서만 이루어진 것이 아니라 이 땅에서도 이루어질 수 있도록 해주신 것이다.
9. 적용(나): 
- 하늘과 이 땅에 동등히 거룩한 곳임을 깨닫는다. 하나님의 사랑이 실천될 수 있게 노력해야겠다. 
- 하나님께서 NKFC에 보내신 모든 청년들을 예정하셨다. 우리를 통해서 조금이라도 예수님을 알게되도록 회원들을 더 보살펴야겠다. 회원들을 위한 기도가 부족한데 회원들을 세심하게 기도해야겠다. 
- 하나님께서 하늘과 이 땅을 동등하게 하신 것처럼 인종의 차이, 높고 낮음은 없다. 이 나라에 온 해외노동자들을 진심으로 사랑하는 마음을 가질 수 있도록 기도해야겠다. 
10. 영적터치(단어/구절)
11. 믿음과 회개 및 감사기도로 마무리', 0, true);

