5.하나님 찾기 (관찰)
- 허물과 죄로 죽은 우리를 살리심
- 우리를 예수 안에서 함께 하늘에 앉히심
- 그리스도 예수 안에서 선한 일을 위하여 우리를 지으심

6.인간 찾기 (관찰)
- 세상 풍조를 따르고 육체의 욕심대로 살아온 우리
- 본질상 진노의 자녀인 우리
- 하나님의 은혜로 믿음으로 말미암아 구원을 받은 우리

7.하나님 찾기 (해석) 
- 인간과 사랑을 나누고자 인간을 창조하신 하나님은 인간이 범한 사망의 죄로 인해 괴로우셨으나 세상이 알 수 없는 지혜로 인간을 용서하시려고 죄 값을 스스로 담당하셨음. 
- 그러므로 이 구원은 우리에게서 난 것이 아니요, 하나님의 선물임
- 하나님은 구원받은 우리가 선한 일을 하기를 원하심. 

8.인간(해석): 
- 아담과 하와가 하나님의 사랑을 누리는 가운데 마귀의 유혹에 넘어가 범죄한 것과 같이 우리는 어둠의 영이 주는 생각을 따라 살아왔다.
- 하나님을 떠나 살고 싶었던, 아담과 하와처럼 우리는 자신을 의지하며 자기 생각대로 살아온 것이다.
- 본질상 진노의 자녀 노릇을 하며 살아온 우리를 하나님이 놀라우신 사랑으로 속량하시고 구원하셨으니, 우리는 갚을 수 없는 큰 선물을 받았다.
- 이 구원은 우리에게서 난 것이 아니기 때문에 우리의 능력인 양 자랑해서는 안 됨.
- 받은 선물에 감사하며 늘 예수님을 생각하고 바라보고 예수님께 나아가야 함

9. 적용(나):
- 선물이 내 능력인 양 자랑하는 죄를 범하지 않도록 조심해야 함.
- 그러나 반대로 세상에서 가장 값진 선물을 받았으니 이 선물을 받은 것으로 인하여 자랑하는 것이 마땅하고, 선물을 주신 분을 높이고 자랑하는 것이 마땅함. 
- 개인적으로 늘 하나님을 찬양하며 높이고, 주변 사람들 앞에서는 하나님의 영광과 찬송이 되어야 함.
- 가정, 직장, 지역사회에서 삶을 나눌 때 늘 함께하시며 보호하시고 도우신 하나님을 자랑해야 함.
- 하나님의 사랑을 전하고 이웃을 섬기면서 동시에 늘 겸손한 가운데 주님을 바라보며, 내가 주인이 아니라 청지기임을 기억하며 살아가는 것이 바로 선한 삶이 될 것임.

10. 영적터치(단어/구절)  
  8   너희는 그 은혜에 의하여 믿음으로 말미암아 구원을 받았으니 이것은 너희에게서 난 것이 아니요 하나님의 선물이라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-01-08', '에베소서', '2장 11절 ~ 22절', '성도의 연합이 자신의 성전을 더 거룩하게 만든다.', '[엡2:11-22]
11 그러므로 생각하라 너희는 그 때에 육체로는 이방인이요 손으로 육체에 행한 할례를 받은 무리라 칭하는 자들로부터 할례를 받지 않은 무리라 칭함을 받는 자들이라
12 그 때에 너희는 그리스도 밖에 있었고 이스라엘 나라 밖의 사람이라 약속의 언약들에 대하여는 외인이요 세상에서 소망이 없고 하나님도 없는 자이더니
13 이제는 전에 멀리 있던 너희가 그리스도 예수 안에서 그리스도의 피로 가까워졌느니라
14 그는 우리의 화평이신지라 둘로 하나를 만드사 원수 된 것 곧 중간에 막힌 담을 자기 육체로 허시고
15 법조문으로 된 계명의 율법을 폐하셨으니 이는 이 둘로 자기 안에서 한 새 사람을 지어 화평하게 하시고
16 또 십자가로 이 둘을 한 몸으로 하나님과 화목하게 하려 하심이라 원수 된 것을 십자가로 소멸하시고
17 또 오셔서 먼 데 있는 너희에게 평안을 전하시고 가까운 데 있는 자들에게 평안을 전하셨으니
18 이는 그로 말미암아 우리 둘이 한 성령 안에서 아버지께 나아감을 얻게 하려 하심이라
19 그러므로 이제부터 너희는 외인도 아니요 나그네도 아니요 오직 성도들과 동일한 시민이요 하나님의 권속이라
20 너희는 사도들과 선지자들의 터 위에 세우심을 입은 자라 그리스도 예수께서 친히 모퉁잇돌이 되셨느니라
21 그의 안에서 건물마다 서로 연결하여 주 안에서 성전이 되어 가고
22 너희도 성령 안에서 하나님이 거하실 처소가 되기 위하여 그리스도 예수 안에서 함께 지어져 가느니라

