2024년 1월 20일 에베소서 2장 11절~22절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 할례(11절), 밖(12절), 없다(12절), 육체(11,12,14절), 십자가(16절), 원수(14,16절), 평안(17절)
4.주제만들기: 성도의 연합이 자신의 성전을 더 거룩하게 만든다.
5.하나님 찾기 (관찰)
- 화평이 되시고, 율법을 폐하심, 하나님 안에서 둘은 새사람으로 지어 화평하게 하심
- 십자가로 화목하게 하시고, 십자가로 원수된 것을 소멸하심
- 직접 오셔서 평안을 전하심
- 예수님이 모퉁이돌이 되어 우리를 연결하여 주시고 주안에서 성전을 이루심
6.인간 찾기 (관찰)
- 바울은 유대인은 할례 받은 자들이고 이방인은 할례받지 않는 자들이었다는 것을 상기시킨다.
- 바울은 예수님으로 인해 둘 사이의 막힌 담이 허물어져 화평을 이루셨으며 성령안에서 함께 나아갈 수 있다고 말한다. 
- 바울은 이방인도 아니고 나그네도 아니고 동일한 시민이며 하나님의 권속이라고 말한다.
7.하나님 찾기 (해석) 
- 예수님께서 오셔서 십자가를 통해 이루신 사랑은 유대인이 자신들에게만 주어진 구원이 아니라 모든 사람에게 동일하게 주어지는 은혜임을 깨닫게 하셨다. 
- 예수님의 사랑이 아니었다면 유대인이 깨닫지 못했을 것이다. 이로 인해 복음이 지금까지 확장되어져 가고 있다.
8.인간(해석):
- 바울은 이방인이 어떻게 구원을 받게 되었는지 설명하며 하나님의 은혜임을 알려준다. 그리고 이제부터는 이방인이 아닌 동일한 시민이며, 하나님의 권속이라는 말로 에베소 성도들에게 힘과 용기를 주었다.
- 바울은 그리스도께서 모퉁잇돌이 되어 각 사람마다 성전을 짓게 하셨다고 했는데 각 건물이 서로 연결하여 준다는 것을 강조했다. 그것은 혼자 하나님이 거하실 처소를 짓는 것이 아니라 예수님을 중심으로 성령 안에서 성도의 연합이 자신의 영적 거룩함에 유익하다는 것을 강조한 것이다.  
9. 적용(나): 
- 나 혼자 잘난 것이 아닌 예수님 안에서 하나 된 공동체의 연합으로 거룩한 삶을 이어갈 수 있음을 고백한다. NKFC라는 공동체를 통해 신앙이 성장하고 거룩한 삶을 살고자 노력할 수 있음을 감사하며 기도해야겠다. 
10. 영적터치(단어/구절)
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-01-09', '에베소서', '3장 1절 ~ 10절', '제목 없음', '(에베소서 3장)
1.  이러므로 그리스도 예수의 일로 너희 이방인을 위하여 갇힌 자 된 나 바울이 말하거니와
2. 너희를 위하여 내게 주신 하나님의 그 은혜의 경륜을 너희가 들었을 터이라
3. 곧 계시로 내게 비밀을 알게 하신 것은 내가 먼저 간단히 기록함과 같으니
4. 그것을 읽으면 내가 그리스도의 비밀을 깨달은 것을 너희가 알 수 있으리라
5. 이제 그의 거룩한 사도들과 선지자들에게 성령으로 나타내신 것 같이 다른 세대에서는 사람의 아들들에게 알리지 아니하셨으니
6. 이는 이방인들이 복음으로 말미암아 그리스도 예수 안에서 함께 상속자가 되고 함께 지체가 되고 함께 약속에 참여하는 자가 됨이라
7. 이 복음을 위하여 그의 능력이 역사하시는 대로 내게 주신 하나님의 은혜의 선물을 따라 내가 일꾼이 되었노라
8. 모든 성도 중에 지극히 작은 자보다 더 작은 나에게 이 은혜를 주신 것은 측량할 수 없는 그리스도의 풍성함을 이방인에게 전하게 하시고
9. 영원부터 만물을 창조하신 하나님 속에 감추어졌던 비밀의 경륜이 어떠한 것을 드러내게 하려 하심이라
10. 이는 이제 교회로 말미암아 하늘에 있는 통치자들과 권세들에게 하나님의 각종 지혜를 알게 하려 하심이니

