그리스도의 크신 사랑을 구하는 성도의 자세
5. 하나님 찾기(관찰)
영원부터 예정하신 하나님
6. 인간 찾기 (관찰)
믿음으로 하나님께 나아감
그리스도의 사랑을 알고
그 너비와 길이와 높이와 깊이가 어떠함을 깨달아
7. 하나님 찾기 (해석)
상상하지 못하는 크신은혜를 가지고 계신 하나님은 믿고 알기를 원하며 깨우치는 그의 자녀들에게 은혜의 충만과 영광을 주시기를 원하신다.
8. 인간 찾기 (해석)
싸늘한 감옥에 갇혀있는 바울은 이미 개인적으로 경험한 은혜받는 비법을 교회 성도들에게 알려주고 있다. 그 비법은 하나님으로 부터 받을 수 있는 은혜의 충만함이다.
일단 그것을 받기 위해서는 간절히 구하는 마음이 필요하다고 보여주고 있다. 그것은 기도이다. 또한 믿음으로 주님께 다가가고 알기위해 노력할때 비로서 주님은 찾는자아게 깨우침을 통하여 그분의 영광과 충만한 은혜를 주시기를 허락 하신다고 바울은 설명하고 있다. 이러한 기본적인 접근을 통하여 더욱 힘쓴다면 더 큰 은혜를 받을 수 있다는 사실이다. 
바울은 이미 경험한 은혜를 나누고자 힘쓰고 있다. 감옥에 갇혀 있는 바울이 세상에서 자유를 가지고 있는 성도를 향하여 진정한 자유를 갖기를 갈망하는 것은 눈에 보이지 않는 영적 세상이 있음을 보여주고있다.
9. 적용(나)
더욱 믿음안에서 주님을 알고 성경으로 깨우침으로 크신 하나님의 충만함의 은혜를 누리도록 힘써야겠다 
10. 영적 터치(단어/구절)
19절: 그너비와 길이와 높이와 깊이가 어떠함을 깨달아 
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

