4.주제 만들기: 만물을 충만하게 하신 그리스도

5.하나님 찾기 (관찰)
- 평안의 매는 줄로 하나 되게 하신 성령 하나님
- 사람들에게 선물을 주신 그리스도
- 만물을 충만하게 하신 예수님

6.인간 찾기 (관찰)
- 부르심을 받은 대로 합당하게 행하라고 권면하는 바울

7.하나님 찾기 (해석) 
- 신자에게 선물을 주시고 만물을 충만하게 하시는 주 예수 그리스도

8.인간(해석): 
- 예수 공동체 또는 신자는 서로를 겸손하고 온유하게 대해야 하며, 서로의 부족한 부분을 오래 참고 주님의 사랑 가운데서 용납해야 한다.
- 각 사람에게 은혜의 선물을 주셨으니 이 선물은 모두 한 분 하나님으로부터 나온 것이다.
- 각 사람이 받은 선물이 다를 수 있으나 같은 분에게 나온 것이므로 서로 하나 되어 사랑하며 살아야 한다.
- 예수님은 만물을 충만하게 하시려고 낮은 곳에 내려오셨다가 높은 곳으로 올라가셨다.
- 우리도 만물을 충만하게 해야 한다.

9. 적용(나): 
- 성경을 보면 교회에는 알곡과 가라지가 있다. 가라지는 알곡이 잘 자라지 못하게 한다.
- 한편 우리 마음에도 육체의 소욕과 죄성이 있고 동시에 성령님도 계신다.
- 신자는 누구나 때때로 육체의 소욕과 죄성에 쓰러질 때가 있는데, 
- 이 때 자신에게 관대하여 자기가 죄지은 것에 대해 쉽게 넘어가거나 자신을 합리화하는 사람이 있다.
- 그러나 이들은 타인이 육체의 소욕과 죄성에 의해 쓰러지면 크게 비난하거나 정죄하곤 한다.
- 세상 사람 중에 남에게 관대하고 자신에게는 엄격한 사람들이 있다.
- 우리 그리스도인이야 말도 남에게 관대하고 자신에게 엄격해야 하는 사람이 아닌가 생각해 본다.
- 주님이 주신 선물이 다르기 때문에 우리는 받은 선물로 사역하고 살아오면서 형성된 인격과 능력으로 사역한다. 
- 그러므로 사역하는 스타일이 서로 다를 수 있다. 나와 일하는 스타일이 다르다는 이유로 남을 비난하면 안 된다. 
- 예수님을 믿는 공동체는 겸손과 온유함, 그리고 주님의 사랑 안에서 서로를 용납해야 한다.
- 그래야만 예수님이 충만하게 하신 그 충만함을 누리며 살 수 있다.

10. 영적터치(단어/구절)  
  10   내리셨던 그가 곧 모든 하늘 위에 오르신 자니 이는 만물을 충만하게 하려 하심이라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

