6.인간 찾기 (관찰)
- 바울은 성도 가진 다양한 은사로 교회에서 맡는 직분이 다름을 설명한다.
- 직분은 성도를 온전하게 하고, 봉사를 하게 하며 그리스도의 몸을 세우게 한다고 말한다.
- 바울은 영적 성장을 강조하기 위해 어린아이와 같지 아니하여 속임수와 유혹에 빠지지 말라고 말한다. 
- 바울은 교회가 연결되어 있으며 서로 도움을 주고 받아 결합된다고 말했다. 이 때 각 지체가 가진 분량마다 역사하여 성장시키고 사랑안에서 스스로 세워진다고 말한다.
- 이방인이 행하는 것을 하지 말도록 강조한다.
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울은 성도의 직분이 다름을 설명하고 직분이 다른 것이 영적 성장과 교회의 성장에 유익이 됨을 말한다. 이 때 자신이 가진 은사에 더해 사랑이 있어야 교회가 스스로 성장할 수 있다고 강조했는데, 은사보다 중요한 것은 영혼을 사랑하는 마음임을 강조한 것이다. 
- 바울은 사랑이 없는 섬김은 시험에 넘어질 수 있음을 알았고 에베소 교회의 성도들이 예수님의 사랑을 품길 원했다.
- 바울은 어린 아이와 같이 유혹에 현혹되지 않도록 영적 성장을 강조했는데 말씀을 제대로 알고 있다면 하나님을 떠난 사람들의 유혹에 넘어지지 않음을 강조했다. 말씀이 제대로 우리 안에 자리 잡아야 함을 일깨워 준다. 
9. 적용(나): 
- 하나님의 말씀이 내 안에 중심이 되도록 생명의 말씀으로 여기고 꾸준히 읽는 습관이 생기길 기도한다. 
- 하나님의 일을 할 때 중요한 것은 예수님이 우리를 사랑하는 마음이 우리 안에 거하는 것이다. NKFC를 떠올리며 내 안에 사랑이 어떠한지 점검하고 기도해야겠다.   
