주님께 순종하는 이유때문에 억울하게 감옥에 갇힌 바울은 불평 한마디 없이 도리어 하나님의 자녀들이 세상에서 행하야 될 덕목들을 가르치고 있다. 우선 바울은 22절에 옛 사람을 벗어 버리고 24절에 새 사람을 입으라고 대조적으로 기록했다. 옛 사람의 배후에는 욕심의 유혹을 유인하는 사탄과 마귀들이 있는 반면에 새 사람 이 되도록 돕는 분은 의와 진리와 거룩하신 하나님이신것을 알수 있다. 한 성도의 마음이 두 사람 즉 옛사람과 새사람이 늘 충돌한다. 옛 사람에 사로 잡힌 사람은 결국 영혼이 썩어져가고 하나님이 원하시는 선한(분을 참기, 용서하기, 친절하게 대하기 등) 삶을 살기가 불가능 하다고 바울은 알려주고 있다. 그러므로 신자들은 늘 주님과 동행하는 삶을 갖도록 힘쓰므로 구원의 날까지 승리의 삶을 살것을 권면하고 있다
9. 적용(나)
날마다 더욱 영적으로 새롭고 성장하도록 힘써야겠다 
10. 영적 터치(단어/구절)
24절: 하나님을 따라 의와 진리의 거룩함으로 지으심을 받은 새사람을 입으라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

