4.주제 만들기: 빛의 열매를 맺으라
5.하나님 찾기 (관찰)
- 자신을 향기로운 제물과 희생제물로 하나님께 드린 그리스도
6.인간 찾기 (관찰)
- 하나님을 본받는 자, 사랑 가운데서 행하는 자가 되라고 권면하는 바울
- 음행하는 자, 더러운 자, 탐하는 자는 우상 숭배자다
- 헛된 말하는 자들과 함께하지 말라
- 빛의 자녀들처럼 행하라
- 주를 기쁘시게 할 것이 무엇인지 시험해 보라
7.하나님 찾기 (해석) 
우리를 구원하시기 위해, 우리가 죄인 되었을 때에 자기 몸을 내어주신 예수님
8.인간(해석): 
- 사랑받는 자녀가 부모를 본받는 것처럼, 하나님께 사랑받는 우리는 하나님을 본받아야 함.
- 우리를 구원하시기 위해, 우리가 죄인 되었을 때에 자기 몸을 내어주신 예수님의 사랑을 닮은 삶을 살아야 함.
- 음행하는 자, 더러운 자, 탐하는 자는 우상숭배자이며, 이 우상숭배자들은 구원받지 못함.
- 하나님의 자녀답게 빛의 열매를 맺어야 하는데, 빛의 열매는 모든 착함과 의로움과 진실함에 있다. 착함과 의로움과 진실함은 모두 예수 그리스도 안에 있다.
- 주님께서 기뻐하시는 일이 무엇인지 연구하고 분별하여 실천하며 살아야 한다.
9. 적용(나): 
- 더러운 말, 어리석은 말, 희롱의 말을 하지는 않는지 주의하며 살아야 한다.
- 예수님을 깊이 체험하고 은혜에 감사하며 예수님과 동행할 때는 심하게 무례한 일을 당해도 험한 말이 나오지 않았다.
- 말씀 묵상과 기도의 시간이 줄어들고 그런 상태가 길어지자, 작은 일에도 마음속에 불평이 생긴다. 분명 시작은 마음부터다. 그리고 불평과 비난과 짜증 섞인 생각이 들기 시작하고, 이내 그것들이 말로 나오기 시작한다.
- 혼잣말로 시작된 악한 말들은 곧 다른 사람들 앞에서도 나오기 시작한다. 
- 나는 주의해야 한다. 이런 것이 시작되고 곧 습관이 되어 버리면 안 된다.
- 이것은 어둠의 열매다.
- 모든 선한 생각, 의로운 생각, 진실된 생각을 하고 이것이 언행으로 드러나야 한다.
- 선, 의, 진실은 예수님으로부터 나온다. 늘 예수님을 깊이 생각하고 바라보고, 예수님께 나아가야만 선과 의와 진실로 살아갈 수 있다.
- 빛의 열매를 맺어 예수님의 빛을 세상에 반사하는 그런 삶을 살아가자. 
10. 영적터치(단어/구절) 
8 너희가 전에는 어둠이더니 이제는 주 안에서 빛이라 빛의 자녀들처럼 행하라
11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

