5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 바울은 열매 없는 일에 참여하지 말고 그것을 책망하라고 말한다. 
- 은밀한 가운데 행하는 것들은 말하기도 부끄러운 것들이었다.
- 그러나 책망 받은 사람도 그리스도로 말이암아 빛이 될 수 있음을 알려주며 어떻게 행할지 주의하여 지혜로운자 같이 행동하도록 권면했다. 
- 악한 세대에서 세월을 아끼고 어리석은 자가 되지 말며 술 취하지 말고 성령으로 충만함을 받으라 권했다. 
- 마음을 다해 노래하고 예수 그리스도의 이름으로 하나님께 감사하라고 권면한다.
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울은 그 시대에 사람들의 악행을 잘 알고 있었다. 인간은 연약한 존재이므로 악행에 쉽게 무너질 수 있는데 그들을 책망하라고 했다. 책망과 동시에 책망이 빛이 되어 예수님으로 말미암아 빛이 될 수 있음을 알려주었는데, 죄로 인해 정죄가 될 사람들에게 희망을 주기 위함이었을 것 같다. 
- 바울은 지혜롭게 행동해야 함을 강조했다. 악한 세대에 신앙을 지키고 살아가는 것은 쉬운 일이 아니기 때문이다. 그러기 위해선 성령 충만함을 강조했는데 마음을 다해 하나님을 찬양하고 매사에 예수님의 이름으로 하나님께 감사하며 성령 충만하기 위한 노력을 해야함을 알려주었다.
9. 적용(나): 마음을 다해 찬양하고 진심으로 하나님께 감사하는 것은 어려운 일이 아닌데 단순하고 명료한 일을 행하지 않음을 회개한다. 삶에서 신령과 진정으로 예배드리는 것으로 성령 충만함을 꾸준히 유지하도록 하나님의 특별한 은혜를 강구해야겠다.
