바울은 교회의 머리 되신 주님을 비유로 건강한  부부간의 건강 지침서를  설명하고 있다. 남편은 주님이 교회를 위하여 생명을 내어주신것 같이 아내를 사랑할것을 권면하고 있다. 즉 온전한 가정을 이루기 위해서는 절대적 헌신과 희생하는 마음을 가져야한다. 반면에 아내도 남편을 향하여 복종 하기를 말하고 있다. 주님께서 교회를 사랑하신것 같이 남편을 존경하고 철저한 섬김의 마음이 있어야 한다는 것이다. 이렇게 부부지간에 서로 존중하고 사랑할때 가정에서부터 "온전한 영광스러운 가정교회"를 세우시려는 주님의 목적임을 바울은 보여주고자 하고있다.

9. 적용(나)
주님의 핏값으로 사신 교회를 더욱 사랑해야겠다

