4.주제 만들기: 온몸을 보호해 주는 하나님의 갑옷을 입으라 

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 우리의 씨름은 인간이 아니라 통치자, 권세자, 이 어둠의 세상 주관자, 하늘에 있는 악의 영이다.
- 진리의 허리띠, 의의 호심경, 평안의 복음의 신발, 믿음의 방패, 구원의 투구, 성령의 검을 가져야 한다.
- 성령 안에서 힘써 기도하라.
- 쇠사슬에 묶인 상태에서도 복음의 비밀을 담대히 알릴 수 있도록 기도를 부탁하는 바울

7.하나님 찾기 (해석) 

8.인간(해석): 
- 쇠사슬에 묶인 상태에서도 교회를 걱정하며 편지하는 바울은, 그리스도인의 싸움의 대상은 인간이 아니라 우리를 꾀는 마귀임을 분명히 말한다.
- 마귀의 속임수에 당하지 않기 위해서 주 안에서 말씀과 기도로 무장하고 마귀를 대적하라고 말한다.
- 말씀으로 무장하고 의롭게 행동하며 복음을 전하는 삶을 살아야 한다.
- 마귀가 생각과 사람을 이용해 불화살을 끊임없이 쏠 것인데, 이것을 막을 무너지지 않는 믿음이 필요하다.
- 생각으로 공격하는 마귀를 무너뜨리는 투구가 필요하며 구원의 확신을 갖고 담대히 나아가야 한다.
- 마귀를 대적할 무기로 성령의 검을 가져야 하는데 이것은 곧 하나님의 말씀이다. 말씀을 읇조리는 삶을 살아야 한다. 말씀을 마음에 새겨놔야 읇조릴 수 있다. 말씀을 읇조리는 삶은 마귀가 함부로 공격하지 못한다.
- 마귀가 공격하면 읇조리던 말씀으로 마귀를 대적해야 한다.
- 이 모든 것을 이루기 위해 성령 안에서 기도해야 한다. 
- 기도 없이는 마귀를 대적할 수 없다.
- 바울은 우리가 마귀와의 전장에 있다는 것을 알려준다.
- 쇠사슬에 묶인 내가 이 절망적인 상황에서도 입을 열어 복음을 전할 수 있도록 기도를 부탁한다.

9. 적용(나): 
- 마귀는 먼저 내 마음속에 있는 나의 죄성을 이용하여 나를 공격한다. 
- 가정, 교회, 일터, 지역사회의 누군가로부터 나의 약점을 파고드는 공격이 들어온다. 
- 내 몸과 영이 지치고 힘들 때 나는 마귀에게 패배하곤 한다.
- 이유 없이 내게 무례하게 행동하거나 비난하는 사람들을 보면 화가 치밀어 오르기도 한다.
- 내 마음속에서 마귀에게 패배하면 곧 관계에 대한 불평과 불신이 싹튼다.
- 이것이 지속되면 결국 사람과 문제가 발생하게 되어 있다.
- 나는 마귀의 간계를 능히 대적하기 위해 하나님이 온몸을 보호해 주시는 갑옷으로 무장해야 한다. 하나님께서 보호해 주시는 온몸의 범위에는 정신도 포함된다.
- 내게는 하나님이 입혀주시는 온몸을 덮는 갑옷이 필요하다. 
- 말씀으로 단단히 무장하고 말씀을 실천하고 복음을 전하는 삶을 살아내야 한다.
- 수없이 쏟아지는, 끊임없는 마귀의 불화살을 버텨낼 믿음이 필요하고, 내가 막지 못한 치명적인 불화살은 예수님께서 막아주신다는 확신이 있어야 한다.
- 우리의 생각을 공격하는 마귀를 대적하기 위해 최후 승리에 대한 확신과 함께 마귀를 대적하는 무기, 세상에 없는 최고의 무기인 성령의 검. 말씀으로 마귀를 베어야 한다.
- 나는 지금 전장에 있다. 이것을 반드시 기억해야 한다.

10. 영적터치(단어/구절)  
   13   그러므로 하나님의 전신 갑주를 취하라 이는 악한 날에 너희가 능히 대적하고 모든 일을 행한 후에 서기 위함이라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

