8.인간(해석):
- 바울은 빌립보 교회 성도들에게 문안하며 복음에 참여하는 일에 동참하고 있는 것을 격려하여 소망을 품게함.
- 바울은 하나님께서 이 일을 시작하셨고 하나님께서 이루실 것이라며 하나님에 대한 신앙의 확신을 잃지 않도록 강조함.
- 바울은 예수 그리스도의 심장으로 사랑한다고 표현하며 예수님의 십자가 사랑만큼 빌립보 성도를 사랑하고 있음을 깨닫게 함.
9. 적용(나): 
- 언제, 어디서나 예수님의 사랑을 품고 사는 마음을 가질 수 있도록 기도해야겠다.
- 손해보고 싶지 않은 마음이 내 안에서 사라지길 기도한다. 
10. 영적터치(단어/구절)
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

