바울을 통하여 더욱 하나님을 더욱 신뢰하고 복음을 담대하게 전파하는 다수의 형제들

7.하나님 찾기 (해석)

8. 인간 찾기 (해석)
14절에 바울의 매임으로 다수의 형제들이 하나님 말씀을 담대하게 전하였다고 말하고 있다. 단순 이성적으로 생각할때는 갇혀있는 바울을 생각할때 자신들도 바울처럼 억압받을까 두려워 피신하거나 갇혀있는 바울을 보며 하나님의 인도하심에 답답한 심정을 충분히 토할수 있는 상황이 아닌가?
그럼에도 그들은 도리어 용기를 내고 있다고 기록되어 있다. 과연 그들이 보여준 담대함은 어디에서 온것일까? 물론 하나님의 전적인 은혜이지만 그 은혜를 끌어낼수 있었던  바울의 믿음과 사명감이라 볼수있다. 비록 열악한 환경이지만 크신 하나님을 신뢰하며 하나님 이 원하시는 복음 전파에 몰입한 바울은 자신이 비록 갇혀있지만 그 또한 허락하시고  계획하신 분이 하나님이라는  확신 속에 큰 믿음이 생겼다고  볼수있다. 무엇보다 복음 전파는 시대와 상황을 초월한 하나님이 간절히 원하시는 일이기에 그 일에 관심을 갖고 헌신한다면 그들에게 하나님은 참여할수있는 믿음을 허락하심을 나타내고 있다.
당장 사역이 막혀 보일지라도 인내하고 사명감을 잊지 않는다면 하나님은 자신을 신뢰하는 자녀들에게 평강과 더불어 영의 눈을열고 큰 믿음을 주신다는 것을 바울이 보여주고 있다.

9. 적용(나)
현재 겪고있는 환경에서 더욱 담대히 복음을 전하는 사람이 되도록 힘써야겠다 

