4.주제 만들기: 그리스도의 복음에 합당한 생활

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 바울은 그리스도로 살기 때문에 죽는 것도 유익하다고 말함
- 사는 것과 죽는 것 중 죽는 것을 택하여 그리스도와 함께 있고 싶으나
- 그리스도인의 유익을 위해 살아 있는 것을 택함
- 하나님이 은혜를 주신 것은 믿음과 더불어 고난도 받게 하려 하심
- 그리스도의 복음에 합당하게 생활하라고 권면함 

7.하나님 찾기 (해석) 

8.인간(해석): 
- 바울은 주님을 깊이 사랑하므로 나는 죽고 그리스도로 살고 있다고 고백하며
- 그리스도와 함께 있는 기쁨을 누리고자 죽는 것을 택하고 싶다고 말한다.
- 그러나 바울은 살아있는 것이 그리스도인들에게 유익이기 때문에 사는 것을 택한다.
- 그리스도인의 믿음의 진보와 기쁨을 위해 살아있어야 함을 확신했기 때문이다.
- 우리는 그리스도의 복음에 합당하게 생활해야 하는데, 이 합당한 생활이란
- 복음의 신앙을 위하여 협력하는 것과 더불어 대적하는 자들 두려워하지 않는 것이다.
- 하나님은 우리에게 믿음의 은혜와 더불어 고난의 은혜도 주셨다.

9. 적용(나): 
- 그리스도인의 유익을 위해 살아야 하는 것을 확신한 바울의 믿음과 마음을 닮고 싶다.
- 예수님을 향한 갈망이 너무나 컸기에 예수님의 마음이 곧 바울의 마음이 된 것이다.
- 믿음과 고난은 항상 같이 온다. 성경은 이것을 은혜라고 말한다. 
- 믿음 없이 구원은 없으며 고난 없이 믿음의 성숙은 없다. 
- 고난이 왔을 때 비로소 믿음이 빛을 발한다.
- 믿음과 고난의 특권을 통해 주님께 더 가까이 나아가는 내가 되고 싶다. 
- 고난 없는 믿음은 없다.

10. 영적터치(단어/구절)  
  29   그리스도를 위하여 너희에게 은혜를 주신 것은 다만 그를 믿을 뿐 아니라 또한 그를 위하여 고난도 받게 하려 하심이라

11. 믿음과 회개 및 감사기도로 마무리
