INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-01-23', '빌립보서', '2장 1절 ~ 10절', '예수님의 사랑을 깨닫는 은혜', '[빌2:1-10]
1 그러므로 그리스도 안에 무슨 권면이나 사랑의 무슨 위로나 성령의 무슨 교제나 긍휼이나 자비가 있거든
