2024년 2월2일 빌립보서 2장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
4.주제만들기: 예수님의 사랑을 깨닫는 은혜
5.하나님 찾기 (관찰)
- 하나님의 본체시나 동등됨을 취하지 않으시고 자신을 비워 종의 형체를 가져 사람들과 같은 모습이 되심
- 사람의 형태로 나타나사 자신을 낮추시고 십자가에서 죽기까지 순종함
- 모든 이름 위에 뛰어난 이름을 주셨고 하늘에 있는 자들이나 땅에 있는 자들과 땅 아래에 있는 자들이 예수님의 이름으로 무릎을 꿇게 하심
6.인간 찾기 (관찰)
- 바울은 권면, 위로, 교제, 자비가 있을 때 마음을 같이하여 한마음을 품고, 어떤 일에든 다툼이나 허영으로 하지 말고 겸손한 마음으로 자신보다 남을 낫게 여기라고 한다.
- 각각 자기 일뿐만 아니라 다른 사람의 일까지 돌보라고 말한다.
7.하나님 찾기 (해석) 
- 하나님 자신이 인간으로 모습으로 인간과 동등됨 삶을 사셨고, 십자가를 지신 사랑과 순종으로 연약한 인간이 예수님의 사랑을 깨달을 수 있는 은혜를 주셨다.  
8.인간(해석):
- 바울은 권면, 위로, 교제 등을 할 때 겸손한 마음을 갖도록 했는데 그리스도 안에서 권면을 하면 자신의 주관적인 생각을 배제할 수 있다. 사랑이 없는 위로는 교만이 될 수 있고 성령 없이 교제와 긍휼, 자비로운 행동은 시험에 들 수 있다. 바울은 현재 감옥에 있는데 성령님과 깊은 교제와 묵상으로 성도의 신앙 생활을 통찰하는 은혜를 깨달았다.
- 특히 예수님께서 이 땅에 오신 이유를 명확히 알고 바라볼 수 있는 지혜가 있었는데 이러한 깨달음은 전적인 하나님의 은혜였을 것이다.
9. 적용(나): 
- 하나님과 교제를 하는 시간이 늘어날수록 깊은 통찰력이 생긴다. 세상에서 내 힘으로 살아갈 수 있는 일들이 있다. 그러나 사소한 일마저도 하나님께 의지한다면 하나님께서 얼마나 기뻐하실까란 생각이 든다. 하나님의 말씀을 깊이 묵상하는 시간을 가져야겠다. 
