15절 기록을 보면 하나님의 자녀들은 세대를 거슬러 세상과 타협하지 말고 흠이 없는 빛들로 나타낼것을 나타내고 있다. 세상과 구분된 온전한 삶을 산다는 것은 결코 쉬운 일은 아닐것이다.
그럼에도 바울은 그렇게 살것을 권면하고 있다. 흠 없는 자녀로 사는것이 자녀의 본분이요 목표라고 할때에 그것을 이루기 위해서는 12절에 "복종" 이라는 단어가 등장하는것을 볼수있다. 무엇보다도 하나님 말씀을 믿고 순종하는 것이 우선순위 임을 강조하고 있다. 그러기 위해서는 16절에 "생명의 말씀을 밝혀" 그리스도의 날에 자랑할 것이 있게 하려고 한다고 한것을 보면 매일매일 성경을 묵상하고 깨우치고 적용하는 삶이야말로 흠 없는 빛의 자녀로 가는 기본적 영적 코스일것은 분명하다. 그러므로 성경을 묵상하는 시간은 인간의 목표를 다시 정검하는 무엇보다 중요한 일 인것을 바울은 주장하고 있다.

9. 적용(나)
하나님 말씀을 더욱 사랑하고 매일매일 깊이 묵상하며 연구하는데 더욱  힘써야겠다 

