8. 인간 찾기 (해석)
바울은 서신서에 빌립보 교회를  돕기위하여 믿음의 형제인 에바브로디도 를 보낼것이라 기록했다. 그런데 문제는 에바브로디도 가 위중한 병에 걸려있음을 알수있다.  바울은 그를 치료 받거나 쉬게 두지 않고 빌립보 교회를 위하여 당연히 보낼것을 마음 먹고 있다. 언제 죽을지도 모르는 거동이 매우 불편한 에바브로디도 에게 허락받고 서신서를 썼는지 궁금한 생각이 든다. 그러나 25절을 보면 바울이 이러한 확신을 기지고 있었던 마음을 엿볼수 있다. "그는 나의 형제요 함께 수고하고 함께 군사 된 자요" 라고 하는 말에 의미가 모든 것이 함축되어 있음을 알수 있다. 그들은 함께 같은 마음으로 주님의 뜻을 알고 있었기에 가능했을것이다. 노년에 감옥에 갇혀있는 바울이나 심한 병에 걸려있는 에바브로디도 의 뜨거운 복음의 열정을 어느 누구도 속박할수도  포기시킬수도 없음을 느끼게 해준다. 

9. 적용(나)
더욱 굳센 믿음을 품고 복음을 위하여  더욱 힝쓰는 참된 일꾼이 되야겠다.

