4.주제만들기: 목적지가 분명한 달리기
5.하나님 찾기 (관찰)
- 푯대를 향해 그리스도 예수 안에서 부르심
- 만물을 복종하게 하실 수 있는 분이시며 낮은 우리를 하나님의 영광과 같이 변하게 하심
6.인간 찾기 (관찰)
- 바울은 자신이 목적을 향해 달려가고 있음을 말한다.
- 바울은 자신을 본받고 그리스도의 십자가를 원수로 여기는 자들은 결국 멸망을 받을 것음 말함
- 하늘의 시민권을 가지고 하나님의 때를 기다리며 낮은 우리를 하나님의 영광스러운 몸과 같이 만들어주실 것이라 말함
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울은 애처로운 마음으로 빌립보 성도들에게 말했다. 그들의 연약함을 안타까워 했을 것이다. 목적지가 분명하지 않은 달리기는 결국 지쳐 쓰러지게 된다. 그러나 목적지가 분명한 달리기는 목적지를 알기 때문에 쉬어갈 수도, 걸어갈 수도 있다. 결국 목적지에 도착할 수 있기 때문이다.
- 바울은 예수님을 따르지 않는 자들이 세상에서 돋보여 보여도 결국 그들의 끝은 멸망이라고 말한다. 예수님 없이 얻게 되는 인기와 명예와 지위는 세상에선 성공한 사람으로 비춰질지 몰라도 하나님 나라에서는 아니다.
9. 적용(나): 
- 오늘도 마포대교로 가서 준비 된 영혼을 만나야겠다.
- 하나님이 기뻐하시는 일을 할 수 있도록 기도해야겠다. 그리고 어디든 달려갈 수 있도록 훈련되어 있어야겠다.
10. 영적터치(단어/구절)
- 달려가노라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-01-28', '빌립보서', '4장 1절 ~ 10절', '제목 없음', '1. 그러므로 나의 사랑하고 사모하는 형제들, 나의 기쁨이요 면류관인 사랑하는 자들아 이와 같이 주 안에 서라
2.  내가 유오디아를 권하고 순두게를 권하노니 주 안에서 같은 마음을 품으라
3. 또 참으로 나와 멍에를 같이한 네게 구하노니 복음에 나와 함께 힘쓰던 저 여인들을 돕고 또한 글레멘드와 그 외에 나의 동역자들을 도우라 그 이름들이 생명책에 있느니라
4. 주 안에서 항상 기뻐하라 내가 다시 말하노니 기뻐하라
5. 너희 관용을 모든 사람에게 알게 하라 주께서 가까우시니라
6. 아무 것도 염려하지 말고 다만 모든 일에 기도와 간구로, 너희 구할 것을 감사함으로 하나님께 아뢰라
7. 그리하면 모든 지각에 뛰어난 하나님의 평강이 그리스도 예수 안에서 너희 마음과 생각을 지키시리라
8. 끝으로 형제들아 무엇에든지 참되며 무엇에든지 경건하며 무엇에든지 옳으며 무엇에든지 정결하며 무엇에든지 사랑 받을 만하며 무엇에든지 칭찬 받을 만하며 무슨 덕이 있든지 무슨 기림이 있든지 이것들을 생각하라
9. 너희는 내게 배우고 받고 듣고 본 바를 행하라 그리하면 평강의 하나님이 너희와 함께 계시리라
10.  내가 주 안에서 크게 기뻐함은 너희가 나를 생각하던 것이 이제 다시 싹이 남이니 너희가 또한 이를 위하여 생각은 하였으나 기회가 없었느니라

