8. 인간 찾기 (해석)
바울은 옥중서신중 하나인  "기쁨"의 주제로 쓴 빌립보서 를 마무리 하면서 성도가 어떠한 자세로 하나님께 간구하며 구할 것인지를 기록했다. 기도와 간구할때에는 감사함의 자세로 할 것을 인지시키고 있다. 모든 지각에 뛰어나신 하나님이 이미 구하는 사람들의 필요와 도울 내용을 알고 계심을 비취고 있다. 그러한 하나님께서 간구하는 자녀들에게 그들의 가장 큰 응답인 평강을 주시고  마음과 생각또한 지켜주신다고 바울은 주장한다. 이보다 더큰 응답은 없을 것이다. 이것을 확신있게 주장하거나  권면할수 있는 바울은 이미 감옥안에서 밝은 분위기의 기쁨을 체험하고 있기 때문이다. 바울은 감옥 안에 있는 것이 아니라 주님 안에서 고난의 기쁨을 누리고 있는듯 하다. 모든 열악한 환경에 처해있더라도 주님이 함께 하신다면 그곳은 기쁨의 동산이 될 수 있음을 바울은 일깨워주고 있다.

9. 적용(나)
어떠한 환경속에서도 하나님께 감사함으로 살아야겠다 

