INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-01-29', '빌립보서', '4장 11절 ~ 23절', '선물, 그리고 풍성한 열매', '빌립보서 4장
11   내가 궁핍하므로 말하는 것이 아니니라 어떠한 형편에든지 나는 자족하기를 배웠노니
12   나는 비천에 처할 줄도 알고 풍부에 처할 줄도 알아 모든 일 곧 배부름과 배고픔과 풍부와 궁핍에도 처할 줄 아는 일체의 비결을 배웠노라
13   내게 능력 주시는 자 안에서 내가 모든 것을 할 수 있느니라
14   그러나 너희가 내 괴로움에 함께 참여하였으니 잘하였도다
15   빌립보 사람들아 너희도 알거니와 복음의 시초에 내가 마게도냐를 떠날 때에 주고 받는 내 일에 2)참여한 교회가 너희 외에 아무도 없었느니라
16   데살로니가에 있을 때에도 너희가 한 번뿐 아니라 두 번이나 나의 쓸 것을 보내었도다
17   내가 선물을 구함이 아니요 오직 너희에게 유익하도록 풍성한 열매를 구함이라
18   내게는 모든 것이 있고 또 풍부한지라 에바브로디도 편에 너희가 준 것을 받으므로 내가 풍족하니 이는 받으실 만한 향기로운 제물이요 하나님을 기쁘시게 한 것이라
19   나의 하나님이 그리스도 예수 안에서 영광 가운데 그 풍성한 대로 너희 모든 쓸 것을 채우시리라
20   하나님 곧 우리 아버지께 세세 무궁하도록 영광을 돌릴지어다 아멘
21   그리스도 예수 안에 있는 성도에게 각각 문안하라 나와 함께 있는 형제들이 너희에게 문안하고
22   모든 성도들이 너희에게 문안하되 특히 가이사의 집 사람들 중 몇이니라
23   주 예수 그리스도의 은혜가 너희 심령에 있을지어다

