4.주제 만들기: 선물, 그리고 풍성한 열매

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 자족하기를 배운 바울
- 바울의 괴로움에 참여한 빌립보 교회
- 바울이 데살로니가에 있을 때 두 번 바울이 쓸 것을 보낸 빌립보 교회
- 선물을 구하는 것이 아니라 교회의 풍성한 열매를 구함
- 내가 받은 것으로 풍족하니 이것은 하나님이 받으실 만한 향기로운 제물이고 하나님을 기쁘시게 한 것이다.
- 하나님께서 너희 모든 쓸 것을 채우실 것이다.
- 문안 인사를 하는 바울

7.하나님 찾기 (해석) 

8.인간(해석): 
- 능력을 주시는 주 안에서 자족하는 법을 배운 바울
- 바울이 어려울 때 도움을 준 빌립보 교회
- 빌립보 교회에 풍성한 열매가 있기를 바라는데, 이것은 내가 선물을 받기 위해서가 아니다. 나는 이미 받은 것으로 풍족하게 지내고 있다.
- 교회에서 보낸 것들은 아름다운 향기이고, 이것은 하나님께서 기쁘시게 받으시는 제물이다.
- 하나님께서 빌립보 교회에 필요한 모든 것을 풍성하게 채워주실 것이다.
- 따뜻하게 인사를 하고 공동체 구성원들의 인사를 전하는 바울
- 그중에는 가이사 집안사람들도 있었는데, 이것으로 보아 황제의 집안에 속한 사람도 바울의 공동체에 있었음을 알 수 있음.

9. 적용(나): 
- 어떤 상황이 와도 주 안에서 만족을 누리는 능력을 받아야 한다.
- 나는 어려서 가난을 경험해 봤으나, 풍부는 경험해 보지 못했다.
- 풍부하게 살아보고 싶은 생각은 있으나, 가난으로 돌아가고 싶은 생각은 전혀 없다.
- 물론, 가난으로 돌아가도 하나님께 감사하며 살 수는 있다.
- 그러나 선택할 수 있다면 가난은 피하고 싶은 것이다.
- 가난은 정말 괴로운 일이다. 
- 이런 면에서 나는 자족의 능력은 없는 것 같다. 
- 가난의 괴로움을 알기에, 내 주변 사역자들이 가난하게 살지 않도록 조금이라도 돕는 삶을 살아야겠다.
- 내가 어려울 때 도와준 분들이 계신다. 이분들은 자족의 능력을 받은 분들이다. 
- 비록 바울처럼 자족의 능력은 없더라도, 바울처럼 풍성한 열매를 위한 기도와 따뜻하게 안부 인사를 할 줄 아는 그런 사람이 돼야 한다. 

10. 영적터치(단어/구절)  
  19   나의 하나님이 그리스도 예수 안에서 영광 가운데 그 풍성한 대로 너희 모든 쓸 것을 채우시리라

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

