골로새 교회가 질서있는 것과 믿음이 굳건한 것이 기쁜 바울
이것으로 보아 교회의 믿음의 성장이 바울의  자랑이었음
세상 철학과 이단에 속지 말고, 신성을 육체에 완전히 채우신 예수를 따르라

9. 적용(나)
오늘날에도 세상 철학과 이단이 넘쳐난다.
예수님을 더 깨달아 알고 닮아, 세상 철학과 이단이 아닌 
주 예수 그리스도를 온전히 따라야겠다.
세상에서 가장 귀한 보화이신 예수님을 많은 이들에게 전해야한다.

