2024년 2월 14일 골로새서 2장 11절~23절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 할례(11,13졀), 일으키심(11절), 십자가(14,15절), 숭배(18,23절)
4.주제만들기: 올바른 신앙을 유지하는 방법
5.하나님 찾기 (관찰)
- 죽은자 가운데서 우리를 일으키심
- 무할례로 죽었떤 우리를 살리심
- 법조문으로 된 증서를 지우심
- 통치자와 권세자들을 구경거리로 만드시고 십자가로 이기심
6.인간 찾기 (관찰)
- 바울은 할례를 받으므로 그리스도의 할례를 받았음을 강조한다.
- 바울은 그리스도의 십자가로 우리를 살라시고 율법을 패하셨으며, 율법주의자들을 십자가로 이기셨다고 말한다.
- 바울은 꾸며낸 겸손과 천사 숭배를 하는 자들은 육신의 생각을 따라 하는 것이며, 그리스도를 붙잡지 않는 자들이라고 말한다.
7.하나님 찾기 (해석) 
- 하나님의 십자가 사랑은 율법주의, 이단과의 영적 전쟁에서 이길 수 있는 실제적인 힘이 있다.
8.인간(해석):
- 바울은 율법주의자들이 그리스도인들을 정죄하고 핍박하는 것에 굴복하지 않기를 바라며 영적 할례를 받은 것을 강조했다. 그리고 예수님께서 몸소 실천하신 일들을 상기시키며 십자가의 은혜와 사랑을 잊지 않도록 권면한다.
9. 적용(나): 
- 예수님은 우리를 위해 십자가를 지신 분인데 나는 예수님의 사랑과 은혜를 너무 쉽게 무시하며 살아가고 있다. 예수님은 세상 만물을 창조하셨고 세상을 다스릴 수 있는 분임에도 세상 일이 우선시되어 그 분의 존재를 무시하며 살아가는 큰 죄를 짓고 있다. 우선 순위에서 예수님과의 교제를 먼저 두는 것조차 예수님을 무시하는 행동이다. 매일 매순간 주님을 바라보며 살아가길 간절히 소망한다. 
10. 영적터치(단어/구절)
온 몸이 머리로 말미암아 마디와 힘줄로 공급함을 받고 연합하여 하나님이 자라게 하시므로 자라느니라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-02-05', '골로새서', '3장 1절 ~ 10절', '제목 없음', '(골로새서 3장)
1. 그러므로 너희가 그리스도와 함께 다시 살리심을 받았으면 위의 것을 찾으라 거기는 그리스도께서 하나님 우편에 앉아 계시느니라
2. 위의 것을 생각하고 땅의 것을 생각하지 말라
3. 이는 너희가 죽었고 너희 생명이 그리스도와 함께 하나님 안에 감추어졌음이라
4. 우리 생명이신 그리스도께서 나타나실 그 때에 너희도 그와 함께 영광 중에 나타나리라
5. 그러므로 땅에 있는 지체를 죽이라 곧 음란과 부정과 사욕과 악한 정욕과 탐심이니 탐심은 우상 숭배니라
6. 이것들로 말미암아 하나님의 진노가 임하느니라
7. 너희도 전에 그 가운데 살 때에는 그 가운데서 행하였으나
8. 이제는 너희가 이 모든 것을 벗어 버리라 곧 분함과 노여움과 악의와 비방과 너희 입의 부끄러운 말이라
9. 너희가 서로 거짓말을 하지 말라 옛 사람과 그 행위를 벗어 버리고
10. 새 사람을 입었으니 이는 자기를 창조하신 이의 형상을 따라 지식에까지 새롭게 하심을 입은 자니라

