7.하나님 찾기 (해석)
하나님은 죽었던 사람들에게 사망의 외투를 벗기시고 생명의 옷으로 갈아입히셨다
그 생명의 옷은 바로 그리스도 이시다
누구든지 그사실을 믿기만 한다면 생명을 얻고 위의것을 보리라 주님은 주문하고 계시다
하나님은 성도라 하더라도 땅의것(음란과 부정과 사욕과 악한 정욕과 탐심)을 즐기는 자들에 대하여 진노하신다
그러므로 예수 그리스도로 새 옷을 입고 본래 하나님의 창조의 목적 이었던 형상대로 지어져 가는것을 원하신다.

8. 인간 찾기 (해석)
땅의 것을 바라지 말고 오직 주님과함께 위의것을 찾는 지세가 참된 성도의 모습이라 바울은 고백하고 있다
9. 적용(나)
세상에서 추구하는 인기를 물리치고 주님의 엉광과 천국의 소망으로만 열심히 살아내야겠다

