8.인간 찾기 (해석)
새로운 그리스도인이 되면 기본적으로 갖추어야될 덕목을 바울은 가르치고 있다. 주안에서 사랑하고 허물있는 사람을 용서하고 차별하지 말고 감사하며 사는 자세를 이루며 사는것이 마땅한 모습이라 설명한다. 어러한 덕목들은 인간의 의지로 하기가 쉽지않으므로 먼저 그리스도께서 성도들에게 보여주신것을 닮아 따르도록 섬세하게 설명한다
특별히 이 많은 덕목들을 지키기 위해서는 14절의 "사랑을 더하라 이는 온전하게 매는 띠니라" 깨우침을 밝히는것처럼 적당한 사랑이 아닌 넘치는 사랑이 있을때만이 더욱 새로운 하나님의 자녀로써의 본분을 지킬것이라 바울은 주장하고 있다

