5.하나님 찾기 (관찰)
- 사람을 외모로 취하지 않으심
6.인간 찾기 (관찰)
- 바울은 자녀를 노엽게 하지 말고, 종들은 상전에게 순종하되 주를 두려워하여 성실한 마음으로 하도록 권면한다. 
- 그리스도를 섬기는 자들이므로 무슨 일을 하든 마음을 다해 주께 하듯 하도록 권면한다.
7.하나님 찾기 (해석) 
- 사람을 외모로 판단하지 않으시는 진정한 신, 유일한 신, 공의로우신 하나님이시다.
8.인간(해석):
- 부모가 자녀에게 덕이 되지 않는 행동 만큼 최악의 모습은 없을 것이다. 바울은 부모로서의 역할도 강조하며 덕이 되는 삶을 살도록 권면했다. 
- 아랫 사람은 윗사람을 잘 따르며 가식적으로 하지 말고 진심을 다해 행동하라고 했는데 주님 대하듯이라는 전제를 달며 순종하기 힘든 상사, 주인도 주님을 생각하며 순종할 수 있는 방법을 알려주었다.
- 무슨 일이든 주님 대하듯 하면 겸손한 마음이 가득할 것이다.
9. 적용(나): 
- 과거 외모로 사람을 판단했던 일과 사람을 외식하듯 판단하여 제한한 행동들을 회개한다. 
- 매일 삶속에서 모든 일들을 주님 대하듯이 하면 좋을텐데 화만 늘어나는 내가 부끄럽다
- 하나님을 의지적으로 생각하며 매일 십자가를 질 수 있길 기도한다.
10. 영적터치(단어/구절)
- 23절 무슨 일을 하든지 마음을 다하여 주께 하듯 하고 사람에게 하듯 하지 말라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-02-08', '골로새서', '4장 1절 ~ 10절', '제목 없음', '(골로새서 4장)
1. 상전들아 의와 공평을 종들에게 베풀지니 너희에게도 하늘에 상전이 계심을 알지어다
2.  기도를 계속하고 기도에 감사함으로 깨어 있으라
3. 또한 우리를 위하여 기도하되 하나님이 전도할 문을 우리에게 열어 주사 그리스도의 비밀을 말하게 하시기를 구하라 내가 이 일 때문에 매임을 당하였노라
4. 그리하면 내가 마땅히 할 말로써 이 비밀을 나타내리라
5. 외인에게 대해서는 지혜로 행하여 세월을 아끼라
6. 너희 말을 항상 은혜 가운데서 소금으로 맛을 냄과 같이 하라 그리하면 각 사람에게 마땅히 대답할 것을 알리라
7.  두기고가 내 사정을 다 너희에게 알려 주리니 그는 사랑 받는 형제요 신실한 일꾼이요 주 안에서 함께 종이 된 자니라
8. 내가 그를 특별히 너희에게 보내는 것은 너희로 우리 사정을 알게 하고 너희 마음을 위로하게 하려 함이라
9. 신실하고 사랑을 받는 형제 오네시모를 함께 보내노니 그는 너희에게서 온 사람이라 그들이 여기 일을 다 너희에게 알려 주리라
10. 나와 함께 갇힌 아리스다고와 바나바의 생질 마가와 (이 마가에 대하여 너희가 명을 받았으매 그가 이르거든 영접하라)

