4. 주제 만들기 
영적 비밀을 알리기를 원하는 바울

5.하나님 찾기(관찰)
전도할 문을 열어주시는 하나님

6.인간 찾기 (관찰)
감사하는 마음으로 기도를 계속할것을 골로새 교회 성도들에게 권면하는 비울
