신실한 일꾼들(두기고 오네시모 마가)
을 보내어 골로새 교회를 돕는 바울

7.하나님 찾기(해석)

8.인간 찾기 (해석)
바울은 기도할때 감사함으로 쉬지말고 깨어 기도하기를 강조하고 있다
기도하는 내용으로는 그리스도의 비밀을 알게하고 전도할 문을 열기를 위하여 간구할것을 요청하고 있다
이 부분에서 깨우치는 것은 3절의 기록부분을 보면 "전도할 문을 우리에게 열어 주사" 로 기록되어 있는것으로 보듯 ''전도'' 는 햐나님이 우리에게 기회를 주시는것을 알수 있다. 노방전도를 하기전에 충분한 기도와 간구가 선행되야하는것을 알려주시는 대목이라 느껴진다
바울은 골로새 교회를 돕기 위하여 자신이 특별히 아끼는 형제들을 동원하여 골로새 교회로 파견함으로써 피차 위로받고 도움을 주는 사랑의 연합의 모습을 보여주고 있다
이러한 기본적인 동럭은 1절의 "하늘에 상전이 계심을 알지어다"기록 처럼  하나님의 주인되심을 바울은 붙잡고 있음에 비롯되었다 볼수있다 

9. 적용(나)
마포대교 전도 전에 복음의 문을 열어달라고 하나님께 더욱 충분히 기도해야겠다 

