6.인간 찾기(관찰)
- 데살로니가 교회에 인사하는 바울, 실루아노, 디모데
- 데살로니가 교회의 믿음을 칭찬하는 바울
- 많은 환난 가운데서도 성령의 기쁨 가운데 말씀을 받고, 주님과 바울 일행을 본받은 데살로니가 교회
- 마게도냐와 아가야에 있는 그리스도인들에게 본이 되고, 믿음의 소문이 각처에 퍼진 데살로니가 교회
- 데살로니가 교회와 바울 일행의 만남부터 예수님의 재림을 기다리는 교회의 소망까지 믿음의 삶에 대해 알고 말하는 각처의 사람들.

7. 하나님 찾기(해석)

8. 인간 찾기 (해석)
- 데살로니가 교회 사람들은 환난 가운데서도 성령 안에서 말씀에 순종하며 살았다.
- 이 믿음의 견고함이 각처에 소문이 났다.
- 바울 일행에게서 본받은 믿음을, 믿음의 삶을 살아내는 데살로니가 교회의 믿음에는 파워가 있었다. 
- 이 파워는 성령의 능력이다. 
- 성령의 사람 바울, 실루아노, 디모데에게 영향을 받은 데살로니가 교회는 주위에 강력한 영향을 미쳤다.
- 오늘날에도 성령의 사람에게 영향을 받은 또 다른 성령의 사람은 주위에 선한 영향을 줄 수 있다.
- 이것은 인간의 능력이나 자기 의지에서 난 것이 아니요 성령님으로부터 나는 것이다.
- 우리 인간은 성령님을 의지하여 성령 안에서 기도하고 말씀으로 살아내고자 늘 힘써야 한다. 

9. 적용(나) 
- 예수님과 사도들로부터 시작된 제자화.. 사도, 스데반과 빌립, 바나바, 바울, 디모데 ... 오늘날의 신자들까지 기독교는 제자화의 과정의 반복으로 유지되고 있다.
- 이 과정의 시작은 예수님이며 제자화는 성령 충만한 사람들이 또 다른 성령 충만한 자에게 본이 되는 것으로 지속된다. 그리고 이 동력은 성령님께서 주시는 것이다.
- 나도 또 다른 성령 충만한 자가 되어 또 다른 성령 충만한 자에게 본이 되는 삶을 살고 싶다.
- 바울 일행을 본받아 그 믿음이 각처에 소문난 데살로니가 교회처럼. 
- 우리 교회가, 그리고 한국교회가 각처에 믿음 좋기로 소문난 교회들이 되기를 소망한다. 

10. 영적 터치(단어/구절)
  8   주의 말씀이 너희에게로부터 마게도냐와 아가야에만 들릴 뿐 아니라 하나님을 향하는 너희 믿음의 소문이 각처에 퍼졌으므로 우리는 아무 말도 할 것이 없노라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-02-12', '데살로니가전서', '2장 1절 ~ 10절', '연약한 자를 위한 완벽한 섬김', '[살전2:1-10]
1 형제들아 우리가 너희 가운데 들어간 것이 헛되지 않은 줄을 너희가 친히 아나니
2 너희가 아는 바와 같이 우리가 먼저 빌립보에서 고난과 능욕을 당하였으나 우리 하나님을 힘입어 많은 싸움 중에 하나님의 복음을 너희에게 전하였노라
3 우리의 권면은 간사함이나 부정에서 난 것이 아니요 속임수로 하는 것도 아니라
4 오직 하나님께 옳게 여기심을 입어 복음을 위탁 받았으니 우리가 이와 같이 말함은 사람을 기쁘게 하려 함이 아니요 오직 우리 마음을 감찰하시는 하나님을 기쁘시게 하려 함이라
5 너희도 알거니와 우리가 아무 때에도 아첨하는 말이나 탐심의 탈을 쓰지 아니한 것을 하나님이 증언하시느니라
6 또한 우리는 너희에게서든지 다른 이에게서든지 사람에게서는 영광을 구하지 아니하였노라
7 우리는 그리스도의 사도로서 마땅히 권위를 주장할 수 있으나 도리어 너희 가운데서 유순한 자가 되어 유모가 자기 자녀를 기름과 같이 하였으니
8 우리가 이같이 너희를 사모하여 하나님의 복음뿐 아니라 우리의 목숨까지도 너희에게 주기를 기뻐함은 너희가 우리의 사랑하는 자 됨이라
9 형제들아 우리의 수고와 애쓴 것을 너희가 기억하리니 너희 아무에게도 폐를 끼치지 아니하려고 밤낮으로 일하면서 너희에게 하나님의 복음을 전하였노라
10 우리가 너희 믿는 자들을 향하여 어떻게 거룩하고 옳고 흠 없이 행하였는지에 대하여 너희가 증인이요 하나님도 그러하시도다

