2024년 2월20일 데살로니가전서 2장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 복음(2,4,9절), 기쁘게하다(4절), 알다(1,2,5절), 전하다(2,9절)
4.주제만들기: 연약한 자를 위한 완벽한 섬김
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 바울은 고난을 당하면서도 데살로니가에 복음을 전한 것을 강조한다.
- 바울의 권면은 하나님을 기쁘게 하기 위함을 말한다.
- 바울은 사람에게 영광을 구하지 않았고 사도로 권위를 주장할 수 있으나 자녀를 키우는 부모와 같이 성도들을 대했다고 말한다.
- 바울은 복음을 위해 자신들의 목숨까지 줄 수 있으며, 그만큼 사랑한다고 말한다. 
- 바울은 복음을 전할 때 부담되지 않도록 자신이 수고로 일한 돈으로 복음을 전했다고 말한다. 이 모든 것은 하나님께서 증인임을 고백했다.
7.하나님 찾기 (해석) 
8.인간(해석):
-  바울은 데살로니가 성도들에게 고난을 당하면서도 복음을 전했다는 이야기를 하는데 복음이 당연한 권리라고 생각할 수 있는 성도들에게 복음은 은혜임을 깨닫게 해주었다. 지금 내가 성경을 읽고 묵상할 수 있는 것도 다 하나님의 은헤이다. 
- 바울의 권면은 하나님을 기쁘시게 하는 일임을 분명히 밝히며 성도들이 오해 없도록 하였다. 
- 또한 사도로 대우 받을 수 있으나 오히려 더 낮은 자세로 섬김 것은 성도 한사람 한사람을 진정으로 사랑했기 때문이라고 했다. 사랑이 있다면 겸손함이 나오고 사람을 외모로 판단하지 않을 것이다.
- 바울은 사역하는 동안 자신의 수고로 일을 하며 복음을 전했는데 다른 사도들은 어떻게 했을지 궁금해지기도 하다. 
9. 적용(나): 
- 사역을 할 때 사랑이 없다면 낮은 자세로 섬길 수 없을 것이다. 내 안에 사랑이 가득할 수 있도록 기도해야겠다. 
- 한 영혼을 위해 목숨을 바쳤던 바울과 같은 삶을 나는 살아갈 수 있을까? 
10. 영적터치(단어/구절)
- 2절 빌립보에서 고난과 능욕을 당하였으나 우리 하나님을 힘입어 많은 싸움 중에 하나님의 복음을 너희에게 전하였노라
- 9절 형제들아 우리의 수고와 애쓴 것을 너희가 기억하리니 너희 아무에게도 폐를 끼치지 아니하려고 밤낮으로 일하면서 너희에게 하나님의 복음을 전하였노라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-02-13', '데살로니가전서', '2장 11절 ~ 20절', '제목 없음', '데살로니가전서 2장)
11. 너희도 아는 바와 같이 우리가 너희 각 사람에게 아버지가 자기 자녀에게 하듯 권면하고 위로하고 경계하노니
12. 이는 너희를 부르사 자기 나라와 영광에 이르게 하시는 하나님께 합당히 행하게 하려 함이라
13. 이러므로 우리가 하나님께 끊임없이 감사함은 너희가 우리에게 들은 바 하나님의 말씀을 받을 때에 사람의 말로 받지 아니하고 하나님의 말씀으로 받음이니 진실로 그러하도다 이 말씀이 또한 너희 믿는 자 가운데에서 역사하느니라
14. 형제들아 너희가 그리스도 예수 안에서 유대에 있는 하나님의 교회들을 본받은 자 되었으니 그들이 유대인들에게 고난을 받음과 같이 너희도 너희 동족에게서 동일한 고난을 받았느니라
15. 유대인은 주 예수와 선지자들을 죽이고 우리를 쫓아내고 하나님을 기쁘시게 하지 아니하고 모든 사람에게 대적이 되어
16. 우리가 이방인에게 말하여 구원받게 함을 그들이 금하여 자기 죄를 항상 채우매 노하심이 끝까지 그들에게 임하였느니라
17.  형제들아 우리가 잠시 너희를 떠난 것은 얼굴이요 마음은 아니니 너희 얼굴 보기를 열정으로 더욱 힘썼노라
18. 그러므로 나 바울은 한번 두번 너희에게 가고자 하였으나 사탄이 우리를 막았도다
19. 우리의 소망이나 기쁨이나 자랑의 면류관이 무엇이냐 그가 강림하실 때 우리 주 예수 앞에 너희가 아니냐
20. 너희는 우리의 영광이요 기쁨이니라

