한번 두번 데살로니가 교회를 방문하려 했으나 사탄의 방해로 막힌 바울
데살로니가 교회를 위로하고 칭찬하는 바울
믿는 성도를 핍박하는 유대인들

7.하나님 찾기(해석)
믿는 자들에게 역사하시는 하나님 말씀
16절에 하나님의 노하심이 끝까지 임했다고 기록되어 있다 이유는 특정 유대인들이 복음의 구원을 막았기 때문이다. 자비로우신 하나님도 구원에 대하여 도전하거나 방해하는 세력들을 결코 용납하지 않으신다. 그만큼 하나님은 누구보다 영혼사랑과 구원에 큰 관심을 갖고 계심을 반증한다는 것을 알수있다 

8.인간 찾기 (해석)
데살로니가 교회를 향하여 큰 위로와 용기를 주는 바울의 모습을 볼수있다. 때때로 성도들에게 찾아올 핍박또한 신도들 누구나 경험하는것임을 알려줌으로써 더욱 견고하게 되기를 바라고 있다
한편 바울의 방문이 이루어지지 않음에 대하여 데살로니가 교회 성도들이 오해하거나 섭섭해 하지 않도록 현질적 상황을 바로 알려줌으로써 불필요한 갈등을 만들지 않고있다
비록 사탄의 방해로 밤문은 당장 이루어지지 못했지만 마음만큼은 그들을  주님안에서 사랑하며 간구하는 바울의 진실성을 느낄수있다
이 시대에도 계속 인간관겨와
사역을 방해하는 사탄의 세력을 감지하고 성도들끼리 더욱 진실되게 지혜롭게 하나님이 주신 사명을 임해야겠다
9. 적용(나)
역사하시는 하나님 말씀을 더욱 붙잡고 살아야겠다  로마서 8장 전체를 암송하도로 힘써야겠다 

