- 이것을 통해 교회를 향한 바울의 사랑이 얼마나 큰지 알 수 있다. 
- 사랑하는 자녀가 성장하기를 바라는 부모처럼, 어서 다시 만나 믿음을 보충해 주고 싶어 한다.
