4.주제만들기: 하나님의 뜻은 거룩함을 실천하는 것
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 바울은 하나님이 기쁘시게 하는 삶을 말한다.
- 바울은 하나님의 뜻은 거룩함을 실천하는 것이고, 음란을 버리고 존귀함으로 아내를 대하며 이방인과 같이 색욕을 따르지 말도록 권면한다.
- 바울은 다만 이러한 일로 형제를 핍박하지 말라고 말하며 하나님께서 이미 신원하셨다고 증언한다.
- 바울은 하나님께서 우리를 부르신 것은 거룩하게 하기 위한 것이며 성령을 저버리는 행위를 하지 않긴 권면한다.
- 바울은 형제 사랑하는 것을 꾸준히 실천하라고 말한다. 
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울은 데살로니가의 성적인 문제를 언급했다. 성은 거룩함을 유지하지 못하게 하는 치명적인 유혹이다. 성적인 유혹은 누구나 쉽게 무너질 수 있기 때문에 거룩함을 실천해야지만 유혹에서 벗어날 수 있다.
- 하나님을 기쁘시게 하는 것은 신령과 진정으로 드리는 예배, 감사의 기도, 하나님을 경외하는 찬양은 당연하고 일상생활에서 거룩함을 실천해야 한다. 일상의 거룩함이 쌓이고 쌓이다보면 습관이 되고 교만으로 가지 않는 한 하나님을 기쁘시게 하는 삶을 실천할 수 있을 것이다. 
9. 적용(나): 
- 거룩함을 실천하기 위한 경건 생활이 습관이 될 수 있도록 결단과 의지를 유지할 수 있는 능력을 구하는 기도를 해야겠다. 
- 형제 사랑을 실천할 수 있는 예수님의 마음을 닮을 수 있도록 기도해야겠다. 
10. 영적터치(단어/구절)
- 3절 하나님의 뜻은 이것이니 너희의 거룩함이라 곧 음란을 버리고
