8.인간 찾기 (해석)
믿음의 사람 바울은 성도들에게는 부활의 소망을 강조하며 데살로니가 성도들을 위로하고 있다. 특별히 로마로부터 믿는 자들이 핍박당하는 가운데 감옥에 갖히거나 죽임을 당하는 일 들이 빈번한 사회적 분위기를 고려한다면 분명 바울의 메시지는 그들에게 큰 도전을 주었을 것이다. 

주님이 마지막때 강림하실 때 이미 죽은자들이 부활하여 예수를 영접함으로 주님과 함께 영원히 연합됨어 진리를 드러내고 있다.

