주의 날에 예수로 말미암아 구원을 받는 믿는자들

7.하나님 찾기(해석)
주님은 마지막 때 산모가 해산의 고통을 느끼는것 처렴 갑자기 임하신다.
그 주님의 때 믿는 자들과 잠자는 자들(불신자)을 구분하시어 구원 또는 심판을 행하신다.
늘 오래참으시고 사랑을 베푸시는 하나님은 주의 날에는 공의의 하나님으로 주관하신다.

8.인간 찾기 (해석)
바울은 주님의 날 이 언제 임할지 모르지만 늘 깨어 있을것을 강력하게 권면하고 있다. 

반드시 임할 주님의 강림을 기다리며 준비하는 사람은 마지막때  천국 찬치에 들어가는 날 이므로 어둠이 더 이상 그들을 괴롭게 하지 못한다.

반면 불신자들은 영원한 어둠속 가운데 멸맘의 길로 들어가는 것이라 설명하고 있다

9. 적용(나)
날마다 주님의 날 을 기다리며 깨어 기도하고 믿음 소망 사랑 을 붙잡고 살아내야겠다 

10. 영적 터치(단어/구절)
9절: 우리 주 예수그리스도로 말미암아 구원을 받게 하심이라 

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

