- 공동체가 서로 화목할 것을 권면하는 바울

7.하나님 찾기 (해석) 

8.인간(해석): 
- 그리스도인은 서로 격려하고 덕을 세우고자 노력해야 한다.
- 교회의 지도자와 어른을 존경해야 한다.
- 게으른 자를 보면 훈계하고 약한 자는 격려하고 힘이 없는 자는 붙들어 주며 모든 사람에게 오래 참아야 한다.
- 악으로 악을 갚지 말게 하고 모든 사람을 대할 때 항상 선을 따라야 한다.
- 항상 기뻐하고 쉬지 말고 기도해야 한다.
- 범사에 감사해야 한다. 이것은 그리스도 예수 안에서 하나님의 뜻이다. 하나님은 감사와 찬양과 경배의 대상이시다. 하나님의 사랑하심과 구원을 열정과 예수님을 생각하면 감사하지 않을 수가 없다.
- 성령을 소멸하거나 예언을 멸시하면 안 된다. 늘 말씀을 가까이하고 기도하고 성령님의 음성에 민감해야 한다.

9. 적용(나): 
- 주변의 그리스도인들에게 덕을 보이는 삶을 살아야 한다.
- 게으른 자를 훈계할 줄 알아야 하는데, 그러기 위해서는 내가 먼저 부지런하고 규모 있는 삶을 살아야 한다.
- 하나님의 뜻을 따르기 위해 늘 성령 안에서 깨어 기도하기를 힘써야겠다.

10. 영적터치(단어/구절)  
