INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-02-19', '데살로니가전서', '5장 21절 ~ 28절', '거룩하게 하시는 것도 흠 없게 하시는 것도 그리스도', '[살전5:21-28]
