4. 주제 만들기 
형벌 받는자와 영광 받을자

5.하나님 찾기(관찰)
공의의 하나님
심판 하시는 하나님 
영광속에 거하시는 하나님 

6.인간 찾기 (관찰)
하나님께 불복종 함으로 심판받는 사람들
믿음으로 하나님께 영광돌리는 사람들
영광을 받는 성도들

7.하나님 찾기(해석)

8.인간 찾기 (해석)
바울은 데살로니가 성도들에게 깊은 위로의 메시지를 보내고있다 지금 받고 있는 환난에 대하여 참고 견디면  주님어 재림때 안식으로 갚아주신다는 내용이다

세상에서도 열심히 공부하고 열심히 밤 낮으로 일하는 까닭은 훗날에 보다나은 안식을 취하기 위함일것이다

그러나 세상에서 받는 안식은 일시적이고 얼마지나지 않아서 금방 삶에 실증이 나며 무기력해지는 것이 일반적 모습이라 볼수 있다

반면에 하나님이 주시는 안식은 영원토록 주님과 더불어 영광을 누리는 세상에서 느낄수없는 느낌일것이다

이러한 축복의 과정을 미리 깨우친 바울은 환난후에 다가올 영광을 미리 경험함으로써 데살로니가 성도뿐만  아니라 모든 사람들에게 일깨움을 주고있다

이러한 진리를 아는  방법은 오직 ''믿음''이라는 사실을 3절을 통하여 알수있다  믿음은 정지되어 있는것이 아니라 계속 자라나야한다  믿음이 성장한 만큼 환난을 허락하신 사랑의 하나님의 더욱 깨우칠수 있다

9. 적용(나)
믿음이 더욱 자라도록 힘써야겠다 

10. 영적 터치(단어/구절)
3절: 믿음이 더욱 자라고

