4.주제 만들기: 불법자에게 속지 말라

5.하나님 찾기 (관찰)
- 주 예수께서 불법자를 죽이시고 강림하여 나타나심으로 폐하시리라

6.인간 찾기 (관찰)
- 예수님이 오신다는 말에 속지 말라고 권면하는 바울
- 예수님이 오시기 전에 배교가 있고, 불법자가 나타날 것임
- 이 불법자는 자기가 하나님이라고 주장할 것이며 많은 사람을 멸망하게 할 것이다.

7.하나님 찾기 (해석) 

8.인간(해석): 
- 사탄의 능력을 입은 강력한 불법자가 나타나서 그리스도인을 속이려 할 것이다.
- 불법자는 능력과 표적과 거짓 기적과 불의의 모든 속임으로 멸망 받을 자들을 속일 것이다.
- 멸망당할 자들이 속임 당하는 이유는 구원하시는 예수님의 사랑을 받아들이지 않기 때문이다. 

9. 적용(나):
- 오늘날에도 기독교를 가장한 이단들이 있다. 그들은 자기가 하나님이라고 주장한다.
- 오늘날 이단도 조심해야 하나 오늘 말씀을 보면 오늘날 이단을 능가하는 강력한 불법자가 나타날 것임을 알 수 있다.
- 그 불법자는 능력과 표적과 기적으로 많은 사람을 속일 것이다.
- 그 불법자가 오기 전에는 주님이 재림하시지 않는다.
- 그러므로 우리 그리스도인들은 주님이 오실 날을 소원하되, 
- 그 날짜를 맞추려 할 것이 아니라
- 날마다 성령 안에서 기도하며 말씀에 순종하는 삶을 살아가야 할 것이다.
- 나의 생이 다할 때까지 세상 속임수에 동요하지 않고 묵묵히 주님을 바라보며 살아야 한다.

