7.하나님 찾기(해석)
기본적으로 주님의 속성은 성도를 악한자에게 지키시는 분이시고 성도들이 영적으로 성장하는 모습을 인내하시며 사랑의 하나님과 더불어  지켜보시며 응원하시는 분이시다

8.인간 찾기 (해석)
바울은 데살로니가 성도들에게 그리스도인들이 피할것과 행할것에 대하여 설명하고 있다. 행함에 있어서 대상이 되는  주님이 어떠한 분이신가 알려주고있다

특별히 바울은 제자 헝제들에게 권의를 내세우기보다는 배려를 베품으로써 그리스도인의 본을 보이고 있다.

말뿐만 아니라 행함의 본을 보이기  위하여 노력하는 바울의 모습으로 인하여 오직 믿음을 통하여 구원을 받는다는 "이신칭의 " 가 더욱 성도들에게 신뢰를 부각시키는것 같다

