바울은 데살로니가 성도들 가운데서도 분쟁을 일으킬수 있는 형제들을 어떻게 대할것에 대하여 가르침을  주고있다

우선 그들(게으른자들, 일하지도 않고 일만 만드는 자들)에게 1차적으로 조용히 일하고 자신의 잉식을 먹기를 권면할것을 당부한다
바울이 "조용히 일하고"라고 기록한것으로 보았을때는  문제를  일으키는 사람들은 스스로가 드러나거나 높아지기를 바라는 마음이 많은 것을 짐작할수있다

1차적 권면했음에도 따르지 않을때는 "사귀지도 말고 부끄럽게 하라"라고 권면한다

그럼에도 바울은 원수와 같이 생각하지 말고 형제같이 권면하리고 당부하고 있다

바울은 공동체안에서 문제를 일으키는 형제들에 대하여 당근과 채찍을 주되 근본적으로는 스스로 변화될것을 기대하며 기다려주는 기본적인 "형제애"의 끈을 잡고 있음을 보여준다

이렇게 바울이 가혹하게 하지 않않던겻은...혹시

바울 스스로 자신도 한때 예수를 따르는 형제들을 핍박했던 영적으로 무지했던  사람으로써 누구나 변화될 가능성을 열어놓고 있었던것 같다


