7.하나님 찾기 (해석) 

8.인간(해석): 
- 다른 교훈과 세상 지식, 율법주의를 가르치는 사람들이 있음
- 이들의 노력은 하나님의 경륜을 이루지 못하고 오히려 변론을 낼 뿐임.
- 사랑이 가장 중요한 것인데, 이들은 사랑에서 벗어나 헛된 말에 빠져있으며 자기가 하는 말도 깨닫지 못하는 자들임.
- 율법은 적법하게 쓰면 선한 것이나, 율법이 제정된 것은 율법을 지키지 못하는 이들을 위한 것임을 알아야 함.

9. 적용(나): 
- 먼저 다른 교리, 신화, 끝없는 족보에 몰두하면 안 된다.
- 그리고 율법을 과하게 강조하는 이를 분별할 줄 알아야 한다.
- 성령 안에서 기도하며 사랑의 마음을 받고, 그 사랑의 힘으로 사람을 대해야 한다.
- 죄를 깨닫게 해 주는 율법을 통해 죄를 깨닫고 늘 죄를 경계하며 살아야 한다.

10. 영적터치(단어/구절)  

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-02-27', '디모데전서', '1장 11절 ~ 20절', '하나님을 알고 난 후에도 지속되어야 할 영적 전쟁', '[딤전1:11-20]
11 이 교훈은 내게 맡기신 바 복되신 하나님의 영광의 복음을 따름이니라
12 나를 능하게 하신 그리스도 예수 우리 주께 내가 감사함은 나를 충성되이 여겨 내게 직분을 맡기심이니
13 내가 전에는 비방자요 박해자요 폭행자였으나 도리어 긍휼을 입은 것은 내가 믿지 아니할 때에 알지 못하고 행하였음이라
14 우리 주의 은혜가 그리스도 예수 안에 있는 믿음과 사랑과 함께 넘치도록 풍성하였도다
15 미쁘다 모든 사람이 받을 만한 이 말이여 그리스도 예수께서 죄인을 구원하시려고 세상에 임하셨다 하였도다 죄인 중에 내가 괴수니라
16 그러나 내가 긍휼을 입은 까닭은 예수 그리스도께서 내게 먼저 일체 오래 참으심을 보이사 후에 주를 믿어 영생 얻는 자들에게 본이 되게 하려 하심이라
17 영원하신 왕 곧 썩지 아니하고 보이지 아니하고 홀로 하나이신 하나님께 존귀와 영광이 영원무궁하도록 있을지어다 아멘
18 아들 디모데야 내가 네게 이 교훈으로써 명하노니 전에 너를 지도한 예언을 따라 그것으로 선한 싸움을 싸우며
19 믿음과 착한 양심을 가지라 어떤 이들은 이 양심을 버렸고 그 믿음에 관하여는 파선하였느니라
20 그 가운데 후메내오와 알렉산더가 있으니 내가 사탄에게 내준 것은 그들로 훈계를 받아 신성을 모독하지 못하게 하려 함이라

3331 생명의 큐티
3:하나님, 인간, 나
