1:감동받는 단어나 구절 찾기(영적터치)

2024년 3월 5일 디모데전서 1장 11절~20절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
- 믿음(14,19절), 교훈(11,18절), 
4.주제만들기: 하나님을 알고 난 후에도 지속되어야 할 영적 전쟁
5.하나님 찾기 (관찰)
- 바울을 충성되이 여겨 직분을 맡기심
- 예수 그리스도께서 먼저 오래참으시는 본을 보이심
6.인간 찾기 (관찰)
- 바울은 비방자, 박해자. 폭행자였으나 긍휼을 입음
- 바울은 주님의 은혜가 예수 안에서 믿음과 사랑과 함께 넘친다고 말함
- 바울은 죄인 중에 괴수라고 말함
- 바울은 영원하신 홀로 하나이신 하나님께 영광을 올림
- 바울은 디모데에게 권면하며 선한 싸움을 싸워 믿음을 지키라고 함. 그리고 믿음을 잃고 사탄에게 넘어간 자들을 언급함
7.하나님 찾기 (해석) 
- 하나님은 은혜로우시며, 자비로우신 분이다. 죄 많은 우리를 누구에게나 회심하고 돌이키고 하나님을 영접할 수 있는 기회를 주셨다.
8.인간(해석):
- 바울은 자신의 과거 행동이 죄임을 깨닫고 본을 보이기 위한 삶을 살았다. 그 과정이 얼마나 힘들었지 생각만해도 숨이 막힌다.(나쁜 뜻은 아님). 그런데 바울은 여전히 자신을 괴수라 여긴다. 바울이 얼마나 겸소한 자세로 사역에 임했는지 알 수 있다. 조금만 나의 기준을 벗어나는 행동이나 말을하는 지체들을 속으로 얼마나 정죄하는지 모른다. 참으로 부끄럽다. 
- 바울은 예수 그리스도를 분석하고 파헤쳤다. 예수님의 공생애 사역과 십자가, 그리고 부활의 모든 과정을 완벽히 이해하고, 하나님의 뜻을 성도들이 깨달을 수 있도록 나름의 방법으로 알려주고 있다. 바울의 깊은 영성은 현대 수많은 성도들에게 도전이 된다. 아마 바울처럼 살고 있는 사람들이 많을 것이다. 하지만 적어도 나는 아니다. 그렇기에 부끄럽다. 
- 그런데 바울과 같이 사는 것은 불가능한 일이 아니다. 우리도 하나님을 영접했고 하나님을 만났으며 성령님이 우리 안에 존재하고 계시다. 그 분과 동행하며 내 자신을 내려놓을 때 하나님의 뜻과 예수님의 사랑을 실천할 수 있다. 힘들지만 우리가 소망을 가지고 도전해볼 수 있다. 
9. 적용(나):
- 성경이 주는 메시지를 온전히 받을 수 있는 영적 상태가 되길 소망한다. 
- 알지 못하고 행한 일이 나의 발목을 잡는다. 죄의 유혹에서 벗어나길 기도한다. 
10. 영적터치(단어/구절)
- 13절 알지 못하고 행하였음이라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-02-28', '디모데전서', '2장 1절 ~ 10절', '제목 없음', '(디모데전서 2장)
1.  그러므로 내가 첫째로 권하노니 모든 사람을 위하여 간구와 기도와 도고와 감사를 하되
2. 임금들과 높은 지위에 있는 모든 사람을 위하여 하라 이는 우리가 모든 경건과 단정함으로 고요하고 평안한 생활을 하려 함이라
3. 이것이 우리 구주 하나님 앞에 선하고 받으실 만한 것이니
4. 하나님은 모든 사람이 구원을 받으며 진리를 아는 데에 이르기를 원하시느니라
5. 하나님은 한 분이시요 또 하나님과 사람 사이에 중보자도 한 분이시니 곧 사람이신 그리스도 예수라
6. 그가 모든 사람을 위하여 자기를 대속물로 주셨으니 기약이 이르러 주신 증거니라
7. 이를 위하여 내가 전파하는 자와 사도로 세움을 입은 것은 참말이요 거짓말이 아니니 믿음과 진리 안에서 내가 이방인의 스승이 되었노라
8. 그러므로 각처에서 남자들이 분노와 다툼이 없이 거룩한 손을 들어 기도하기를 원하노라
9. 또 이와 같이 여자들도 단정하게 옷을 입으며 소박함과 정절로써 자기를 단장하고 땋은 머리와 금이나 진주나 값진 옷으로 하지 말고
10. 오직 선행으로 하기를 원하노라 이것이 하나님을 경외한다 하는 자들에게 마땅한 것이니라

