2024년 3월6일 
디모데전서 2장1절~10절
1.1분기도
2.본문성경 읽기(3번)
3. 반복단어찾기(같은 의미단어 포함)
간구/기도/도고: 1절 5절 8절 
하나님: 3절 4절 5절(2) 10절
예수: 5절(2) 6절(2)
모든 사람: 4절 6절
원함: 4절 8절

4. 주제 만들기 
기도의 중요성

5.하나님 찾기(관찰)
한 분이신 하나님
하나님과 사람 사이에 중보자이신 예수

6.인간 찾기 (관찰)
간구와 기도 그리고 중보기도를 높은 위치에 있는 사람들을 위햐여 더욱 할것을 권면하는 바울
이방인의 스승인 바울

7.하나님 찾기 (해석)
오직 한 분이신 하나님은 모든 인간들이 한명도 빠짐없이 구원 받기를 원하신다. 그것이 하나님의 본심 임을 4절에 명확하게 기록되어 있다

뿐만아니라 구원받은 사람은 각자마다 하나님이 원하시는 진리를 아는 데 까지 성장되기를 원하신다.

8.인간 찾기 (해석)
바울은  하나님을 경외 하는 일은 성도로써 마땅히 행하야할 덕목이라 설명한다 그일을 선행 이라고 한다면 행위로는 "기도" 임을 강조하고 있다

기도의 대상으로는 특별히 임금이나 높은 위치에 있는 자들을 위하여 중보기도 하라함은 백성들이 평안한 생활을 영위됨에 큰 영향을 끼칠수 있기때문이다
 이부분은 지혜에 관한 기도의 내용이라 생각할수 있다

기도할때 마음가짐으로는 겸손함을 주장하고 있다. 8절에 보면 남자들은 "분노와 다툼이 없이 거룩한 손을 들어 기도하기를 원하노라" 기록되어있듯이 자신이 원하는 분위기가 아니어도 마음을 다스리고 거룩한 마음을 갖도록 도와주는것은 겸손한  마음 일것이다

5절에 이미 중보기도의 아이콘으로 겸손하심으로 본을 보여주고 계시는 예수그리스도 처럼 바울은 성도들도 그렇게 하기를 권면하고 있다

9. 적용(나)
성령충만 함을 잘 유지하며 늘 깨어  기도하되 특별히 나라별 리더들을 위하여 더욱 간구 해야겠다

10. 영적 터치(단어/구절)
4절: 진리를 이는 데에 이르기를 원하노라

11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-02-29', '디모데전서', '2장 11절 ~ 15절', '겸손히 믿음 안에서 맡겨진 일을 하라', '디모데전서 2장
11   여자는 일체 순종함으로 조용히 배우라
12   여자가 가르치는 것과 남자를 주관하는 것을 허락하지 아니하노니 오직 조용할지니라
13   이는 아담이 먼저 지음을 받고 하와가 그 후며
14   아담이 속은 것이 아니고 여자가 속아 죄에 빠졌음이라
15   그러나 여자들이 만일 정숙함으로써 믿음과 사랑과 거룩함에 거하면 그의 해산함으로 구원을 얻으리라

3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2024년 3월 8일 디모데전서 2장 11~15절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
여자: 11, 12, 14, 15
아담: 13, 14

4.주제 만들기: 겸손히 믿음 안에서 맡겨진 일을 하라

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 여자가 속아 죄에 빠졌음

7.하나님 찾기 (해석) 

8.인간(해석): 
- 남자와 여자 중 현실 감각과 정서, 사회적 지능 등 여자가 남자보다 우수한 부분이 많다.
- 그런 면에서 남자는 여자를 존중할 뿐 아니라 여자의 말을 잘 들을 필요가 있다.
- 그럼에도 불구하고 바울이 여자는 순종하며 조용히 배우라고 말하는 데에는 이유가 있을 것이다.
- 물론 시대적 상황, 사회 문화적 요소를 배제할 수 없으나, 오늘날보다도 더 높은 차원의 평등을 이야기한 바울과 초대교회의 역사를 볼 때 이 부분을 보다 영적인 것으로 해석할 필요가 있다.
- 자매들은 이 구절이 마음에 들지 않을 수 있으나 남녀의 구분 없이 한 번 깊이 생각해 볼 문제다.
- 바울이 지적하는 것은 원죄에 대한 것이다. 여자가 남자보다 뛰어난 어떤 부분에 의해, 또는 우리가 모르는 그 어떤 면으로 인해 사탄이 아담이 아니라 하와를 유혹의 대상으로 삼았으며 그 약점으로 인해 사탄의 유혹에 빠졌다는 가능성을 배제할 수 없다.
- 바울은 믿음 안에서 말씀 안에서 순종하며 정숙하게 사는 것으로 이 문제를 해결할 수 있다고 말하고 있다.
- 그러나 이 말씀은 남녀를 떠나서 우리 모든 그리스도인들이 적용해야 하는 부분이라는 것을 간과해서는 안 되겠다.
- 말씀에 순종하고 조용히 배우는 것은 여자뿐만 아니라 남자에게도 필요한 것이다.

9. 적용(나): 
- 나는 과연 말씀 안에서 순종하고 살아가고 있는가, 조용히 겸손한 마음으로 배우고 있는가 점검해 보면, 그렇지 못할 때가 많음을 깨닫게 된다.
- 하와가 지녔던 원죄의 원인은 나도 지니고 있다. 늘 깨어 기도하면서 정숙하고 겸손한 마음을 유지하려고 노력해야 한다.
- 나는 하나님의 피조물이고, 하나님의 자녀임을 기억하고, 늘 하나님을 경외하며 살아가야 한다.

10. 영적터치(단어/구절)  

11. 믿음과 회개 및 감사기도로 마무리
12. 받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-03-01', '디모데전서', '3장 1절 ~ 10절', '직분자가 갖추어야 할 것들', '[딤전3:1-10]
1 미쁘다 이 말이여, 곧 사람이 감독의 직분을 얻으려 함은 선한 일을 사모하는 것이라 함이로다
2 그러므로 감독은 책망할 것이 없으며 한 아내의 남편이 되며 절제하며 신중하며 단정하며 나그네를 대접하며 가르치기를 잘하며
3 술을 즐기지 아니하며 구타하지 아니하며 오직 관용하며 다투지 아니하며 돈을 사랑하지 아니하며
4 자기 집을 잘 다스려 자녀들로 모든 공손함으로 복종하게 하는 자라야 할지며
5 (사람이 자기 집을 다스릴 줄 알지 못하면 어찌 하나님의 교회를 돌보리요)
6 새로 입교한 자도 말지니 교만하여져서 마귀를 정죄하는 그 정죄에 빠질까 함이요
7 또한 외인에게서도 선한 증거를 얻은 자라야 할지니 비방과 마귀의 올무에 빠질까 염려하라
8 이와 같이 집사들도 정중하고 일구이언을 하지 아니하고 술에 인박히지 아니하고 더러운 이를 탐하지 아니하고
9 깨끗한 양심에 믿음의 비밀을 가진 자라야 할지니
10 이에 이 사람들을 먼저 시험하여 보고 그 후에 책망할 것이 없으면 집사의 직분을 맡게 할 것이요

3331 생명의 큐티
3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2024년 3월 8일 디모데전서 3장 1절~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)
4.주제만들기: 직분자가 갖추어야 할 것들
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 바울은 감독의 직분을 얻는 자가 갖추어야 할 것들에 대해 말했다.
- 감독자는 아내의 남편으로, 절제, 신중, 단정, 남을 섬기는 일, 술을 즐기지 않는 태도, 폭력적이지 않고, 관용하는 마음으로 다투지 않으며, 돈을 사랑하지 말아야 한다고 말했다.
- 특히 가정을 다스리는 것을 강조했다
- 집사는 외부인들에게도 인정 받는 자여야 하며, 선한 양심으로 비밀을 지키는 자여야 한다고 말한다. 
- 바울은 이 모든 것을 시험하여 보고 난 후에야 집사 직분을 주도록 권면했다. 
7.하나님 찾기 (해석) 
8.인간(해석):
- 감독자의 직분, 집사의 직분은 쉽게 얻거나 맡을 수 있는 직분이 아니다. 바울이 권면한 조건들을 지킨다면 교회에서 일어나는 일들을 사전에 예방하고 다양한 상황에서도 지혜롭게 대처할 수 있는 직분자들이 교회를 잘 지탱해줄 것이다. 
- 바울은 가정에서의 역할을 강조했는데, 가정이 온전하지 않은 상태로 사명감으로 섬김을 감당했을 때 자신은 섬김으로 인해 은혜와 기쁨이 넘칠지 모르지만 그로인해 상처 받고 시험 당하는 가족을 염려했을 수도 있다. 아니면 가족이 섬김에 짐이 될 수 있으니 가정을 먼저 다스리도록 권면했을 수 있다. 
9. 적용(나): 
- 바울은 하나님의 시선으로 세상을 바라보는 통찰력이 뛰어났다. 무엇보다 가정을 소중히하고 가정이 화목해질 수 있도록 노력해야겠다. 간절한 마음으로 아내와 자녀를 위해 기도해야겠다.
- 거저 받은 직분을 지금이라도 바울이 권면한 책무를 성실히 이행하도록 노력해야겠다. 
10. 영적터치(단어/구절)
- 5 (사람이 자기 집을 다스릴 줄 알지 못하면 어찌 하나님의 교회를 돌보리요)
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-03-02', '디모데전서', '3장 11절 ~ 16절', '제목 없음', '(디모데전서 3장)
11. 여자들도 이와 같이 정숙하고 모함하지 아니하며 절제하며 모든 일에 충성된 자라야 할지니라
12. 집사들은 한 아내의 남편이 되어 자녀와 자기 집을 잘 다스리는 자일지니
13. 집사의 직분을 잘한 자들은 아름다운 지위와 그리스도 예수 안에 있는 믿음에 큰 담력을 얻느니라
14.  내가 속히 네게 가기를 바라나 이것을 네게 쓰는 것은
15. 만일 내가 지체하면 너로 하여금 하나님의 집에서 어떻게 행하여야 할지를 알게 하려 함이니 이 집은 살아 계신 하나님의 교회요 진리의 기둥과 터니라
16. 크도다 경건의 비밀이여, 그렇지 않다 하는 이 없도다 그는 육신으로 나타난 바 되시고 영으로 의롭다 하심을 받으시고 천사들에게 보이시고 만국에서 전파되시고 세상에서 믿은 바 되시고 영광 가운데서 올려지셨느니라

