교회를 집으로 삼으시는 살아계신 하나님
영광 가운데 올려지시는 예수님

6.인간 찾기 (관찰)
예수님을 높이는 바울

7.하나님 찾기 (해석)
전능하신 하나님은 어디에나 계시며 어디에서나 거하실수 있다 그럼에도  하나님은 특별히 교회를 그분의 처소로 삼으시기를 원하심을 알수있다 
그 하나님 집은 거룩하며 경건한 장소이다

비록 믿음이 연약하고 죄인된 모습으로 교회안에 들어 오더라도 그들이 진심으로 회개하면 그곳에서 주님의 용서와 자비를 통한 연합의 비밀이 생김을 알수있다

그래서 46절 "크도다 경거의 비밀이여"라고 선포된듯 하다
이성적으로 이해할수 없는 크신 하나님의 사랑과 은혜가 주님을 통하여 만국에 전파되며 마지막때 영광가운데 올려지신다고 기록되어 있다

8.인간 찾기 (해석)

9. 적용(나)
죄인을 경건케 삼으시는 하나님을 더욱 높여드려야겠다

10. 영적 터치(단어/구절)
