경건의 유익

7.하나님 찾기 (해석)

8.인간 찾기 (해석)
바울은 경건의 연단을 주문하고 있다 육체의 연단도 유익하지만 경건은 생활속에 큰 유익을 준다는 것이다 

경건의 사람이 되기 위해서는 5절의 기록처럼 "말씀과 기도" 로 가능 하다고 말하고 있다

경건한 사람에게 나타나는 현상으로는 모든 소망은 오직 하나님께 있음을 깨우치게 됨을 바울은 주장하고 있다

