INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-03-04', '디모데전서', '4장 11절 ~ 16절', '믿는 자에게 본이 돼라.', '디모데전서 4장
11   너는 이것들을 명하고 가르치라
12   누구든지 네 연소함을 업신여기지 못하게 하고 오직 말과 행실과 사랑과 믿음과 정절에 있어서 믿는 자에게 본이 되어
13   내가 이를 때까지 읽는 것과 권하는 것과 가르치는 것에 전념하라
14   네 속에 있는 은사 곧 장로의 회에서 안수 받을 때에 예언을 통하여 받은 것을 가볍게 여기지 말며
15   이 모든 일에 전심 전력하여 너의 성숙함을 모든 사람에게 나타나게 하라
16   네가 네 자신과 가르침을 살펴 이 일을 계속하라 이것을 행함으로 네 자신과 네게 듣는 자를 구원하리라

3:하나님, 인간, 나
3:관찰, 해석, 적용
3:반복단어찾기, 질문하기, 대상이되어봄(본문) 
1:감동받는 단어나 구절 찾기(영적터치)

2024년 월 일 장 1~10절
1.1분기도
2.본문성경 읽기(3번)
3.반복단어 찾기(형광펜 추천)

4.주제 만들기: 믿는 자에게 본이 돼라.

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 말과 행실과 사랑과 믿음과 정절에서 본이 되야 함을 명심하라
- 읽는 것과 가르치는 것과 권하는 것에 전념하라
- 예언을 통해 받은 은사를 가볍게 여기지 말고 모든 일에 전심전력하라
- 자신과 가르친 일을 잘 살펴라

7.하나님 찾기 (해석) 

8.인간(해석): 
- 교회의 지도자로서 믿는 자들에게 본이 될 것을 명하는 바울
- 교회에서 본이 되기 위해서는 성경을 읽는 것에 전념하고, 성경을 가르치는 것에 전념하고, 권면하는 것에도 전념해야 한다.
- 받은 은사는 가볍게 여기면 안 되며, 교회를 위해 성도를 위해 전심전력으로 사용해야 한다.
- 자신을 살피되 가르친 것과 자신을 잘 살펴 가르친 일을 조심하여 지키는 사람이 돼야 함.
- 이것을 계속해야 자신도 구원받고 디모데에게 가르침을 받고 디모데의 모습을 보는 성도들도 구원할 수 있다. 

9. 적용(나): 
- 몇 년 동안 아침마다 간절히 바라며 기도하는 구절이다.
- 그러나 본이 되는 것도, 전념하는 것도 매우 어렵다는 것을 느낄 때가 많다.
- 받은 은사로 교회를 일터를 섬기는 일에 전심전력하는 것도 힘들 때가 많다.
- 기쁠 때나 슬플 때가 평안할 때나 고난 가운데서도 늘 한결 같아야 하는 것이 정말 힘들 때가 있다.
- 믿었던 지체들과 힘든 일이 있거나 가족과 일터에서 괴로운 일이 있을 때 한결같이 섬기는 것은 정말이지 너무나 어렵다.
- 그러나 모든 상황 가운데에서 위와 같은 바울의 권면을 이루며 살아가는 것이 주님의 뜻일 것이다. 
- 어떤 상황 속에서도 주님을 바라보며, 여러 가지 일들을 겪으며 성장하는 나와 교회를 바라며 기대하며 묵묵히 살아내는 그런 사람이 되고 싶다.
 
10. 영적터치(단어/구절)  
