- 바울은 다양한 교회 구성원에 대한 대우에 대해 강조하고 있다.
- 늙은자를 아버지처럼, 젊은이들을 형제처럼, 늙은 여자들을 어머니처럼, 젊은 여자들은 순결함으로 대하도록 권면했다.
- 과부를 존대하고, 과부의 가족은 과부에게 효를 실천하며 외로운 과부는 기도와 간구로 이겨내도록 권면했으며, 향락을 좋아하는 과부는 영적으로 죽은자로 간주했다.
- 바울은 권면으로 과부가 책망 받지 않도록 했으며, 자기 가족을 돌보지 않는 자들은 악한 자라고 말하였다. 
7.하나님 찾기 (해석) 
8.인간(해석):
- 교회에는 다양한 구성원이 존재하며 연령이 각각 다를 것이다. 교회가 본질에 집중하지 못하고 다양한 구성원들의 개성으로 또는 연령으로 인한 세대의 차이로 분쟁이 있어서는 안된다. 그렇기에 바울은 지혜로운 해결책을 제시해주었다.
9. 적용(나): 
- 내 안에 바울이 말한 마음이 새겨져 있다면 교회에서 성도들을 존중하고 겸손한 자세로 따를 수 있을 것이다. 교회 성도들을 가족과 같이 여기며 따르도록 노력해야겠다.
- NKFC내에도 마찬가지다. 서로 존중하고 배려하는 문화가 잘 정착되도록 나의 행동에 주의를 기울여야겠다.
