6.인간 찾기 (관찰)
- 아무 일도 불공평하게 하지 말라
- 경솔히 안수하지 말라
- 다른 사람의 죄에 간섭하지 말라
- 자신을 지켜 정결하게 하라
- 죄는 숨길 수가 없다

7.하나님 찾기 (해석) 

8.인간(해석): 
- 모든 일은 공평하게 처리해야 한다.
- 안수는 신중해야 한다. 받지 말아야 할 사람이 받으면 교회가 위태해질 수 있다.
- 죄에는 간섭할 필요가 없다. 죄와 연관된 일을 하지 말라. 죄인의 길에 서지 말라.
- 정결하기 위해 자신을 지켜야 한다.
- 선행도 죄도 숨길 수가 없다.
- 정결을 위해 포도주를 마시지 않는 것도 중요하지만 건강을 위해서는 사용해도 괜찮으니 조금만 써라.
- 눈에 드러나는 죄(선행)가 있고, 드러나지 않는 죄(선행)도 있지만, 결국에는 모든 것이 드러난다. 
- 눈에 보이는 죄(선행)가 전부가 아니다. 
- 보이지 않는 곳에서도 죄를 짓지 않는 것이 중요하다.

9. 적용(나): 
- 사람을 대할 때나 일을 할 때 불공평하게 하는 것은 없는지 잘 살펴야 한다.
- 마음속으로 짓는 죄에 민감해야 하며, 
- 혼자 있을 때 내가 무엇을 하는지, 그리고 어떤 생각을 많이 하는지 늘 점검해야 한다.    

