5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 바울은 종으로서의 역할을 말하며 상전을 잘 모시고 하나님의 이름이 욕되지 않게 행동하라고 권했다. 
- 바울은 그리스도의 말씀과 경건에 대한 교훈을 따르기를 권했으며, 교만한 마음으로 변론과 언쟁을 좋아하는 자는 다툼이 일어난다고 했다. 
- 바울은 자족하는 마음이 있으면 경건이 큰 이익이 된다고 하였는데 부하려는 자는 시험과 올무와 어리석고 해로운 욕심으로 빠질 수 있으며, 이는 멸망에 빠지게 한다고 했다. 
- 돈을 사랑하는 것은 악의 뿌리가 내며 믿음을 떠나 근심으로 자기를 찌르게 한다고 말한다.
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울은 교회에서 공통적으로 일어나는 일들을 잘 알고 있었다. 교회를 다니고 성경을 알면 하나님의 마음을 품고 사랑을 실천하는 것이 아니라 자신의 명예와 지식을 뽐내기 위해 사용하거나 잘못된 해석으로 교회를 힘들게 함을 반복적으로 알려준다. 이러한 자들에게 미혹되지 말고 신앙을 잘 지키질 권면하고 있다. 
- 바울은 부를 축적해보지도 않았는데 어떻게 물질을 쫓는 자의 결말을 마치 경험한 사람처럼 표현했는지 모르겠다. 하지만 바울은 물질을 따르는 자의 결말을 정확히 알았다. 
9. 적용(나): 
- 물질을 쫓는 삶을 살고 있음에도 멸망에 빠지지 않게 해주신 하나님께 감사하다. 자족하며 경건을 쫓아 살아가는 것을 먼저 실천해야겠다. 
- 과거의 부끄러운 죄들을 반복하지 않도록 간절히 기도해야겠다.
- 오늘 용기내어 신우회를 만들었는데 믿는 상사인 분을 잘 섬겨서 신우회가 활성화 되도록 하나님의 축복을 기도해야겠다.
10. 영적터치(단어/구절)
- 6 그러나 자족하는 마음이 있으면 경건은 큰 이익이 되느니라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-03-09', '디모데전서', '6장 11절 ~ 21절', '제목 없음', '(디모데전서 6장)
11.  오직 너 하나님의 사람아 이것들을 피하고 의와 경건과 믿음과 사랑과 인내와 온유를 따르며
12. 믿음의 선한 싸움을 싸우라 영생을 취하라 이를 위하여 네가 부르심을 받았고 많은 증인 앞에서 선한 증언을 하였도다
13. 만물을 살게 하신 하나님 앞과 본디오 빌라도를 향하여 선한 증언을 하신 그리스도 예수 앞에서 내가 너를 명하노니
14. 우리 주 예수 그리스도께서 나타나실 때까지 흠도 없고 책망 받을 것도 없이 이 명령을 지키라
15. 기약이 이르면 하나님이 그의 나타나심을 보이시리니 하나님은 복되시고 유일하신 주권자이시며 만왕의 왕이시며 만주의 주시요
16. 오직 그에게만 죽지 아니함이 있고 가까이 가지 못할 빛에 거하시고 어떤 사람도 보지 못하였고 또 볼 수 없는 이시니 그에게 존귀와 영원한 권능을 돌릴지어다 아멘
17. 네가 이 세대에서 부한 자들을 명하여 마음을 높이지 말고 정함이 없는 재물에 소망을 두지 말고 오직 우리에게 모든 것을 후히 주사 누리게 하시는 하나님께 두며
18. 선을 행하고 선한 사업을 많이 하고 나누어 주기를 좋아하며 너그러운 자가 되게 하라
19. 이것이 장래에 자기를 위하여 좋은 터를 쌓아 참된 생명을 취하는 것이니라
20. 디모데야 망령되고 헛된 말과 거짓된 지식의 반론을 피함으로 네게 부탁한 것을 지키라
21. 이것을 따르는 사람들이 있어 믿음에서 벗어났느니라 은혜가 너희와 함께 있을지어다

