4. 주제 만들기 
믿음의 선한  싸움을 싸우라

5.하나님 찾기(관찰)
만물을 살게 하신 하나님 
기약이 이르면 나타나심을 보이실 하나님 

6.인간 찾기 (관찰)
하나님의 사람 디모데
믿음의 선한 싸움을 싸울것을 권면하는 바울
재물에 소망을 두지말기
선한 사업을 많이 하고 나누어 주기를 좋아하며 너그러운 자가 되기

7.하나님 찾기 (해석)
하나님은 디모데와 모든 믿는 자녀들이 이 땅에 사는동안 믿음의 싸움을 요구하신다.  그냥 싸움이 아니라 선한 싸움을 싸우라고 명령하셨다.

그 선한 싸움이란 우리의 대장이신 예수그리스도가 이미 승리하셨고 보여 주셨던 행위일것이다
13절에 빌라도를 향하여 선한 증언을 하신 분이 우리 구세주 예수님 이시다

자녀들이 이 땅에서의 선한 싸움을 싸울때 승리 하도록 도우실뿐만 아니라 마지막때 나타나심을 보이실 전능하신 하나님 이시다

8.인간 찾기 (해석)
바울은 자신이 이미 경험하고 있는 믿음의 선한 싸움을 싸우라고 자신의 영적아들인 디모데 예게 권면하고 있다. 이 선한 싸움은 디모데 뿐만아니라 이시대를 살고 있는 모든 믿는 성도를에게 적용되는 내용이다 

다메섹으로 가서 예수믿는 형제들을 잡아 감옥에 가두기 위하여 살기넘치는 눈으로 다니었다.
그 사울 청년이 이제는 바울이 되어 부드럽고 따뜻한 느낌의 싸움조차도 선하게 하라 당부하는 변화된 모습을 만난다

바울이 변화된 주된 원인은 그 에게 찾아오신 주님의 은혜라 볼수있다.
그 은혜를 받고 성도가 된 바울이 지속적으로 그 은혜를 붙잡을수 있었던 것은 온전히 소망을 하나님께 두었기 때문에 가능했다

하나님께 소망을 두는 사람은 재물에 소망을 두지않고 믿음의 선한 사업을 많이 하고 나누어 주기를 좋아하며 너그러운 사람 이라 말하고 있다

9. 적용(나)
믿음안에 다가오는 다양한 삶의 무게들을 잘 견디며 승리하는 삶을 살도록 더욱 노력해야겠다 

