5.하나님 찾기 (관찰)
- 죽은자 가운데서 살아나심
6.인간 찾기 (관찰)
- 바울은 예수 안의 은혜 가운데 강하고 많은 증인 앞에서 자신이 한 말을 충성된 자들에게 부탁하라고 말했다. 
- 바울은 병사로 고난에 동참하로 하며, 병사는 자기 생활에 얽매이지 않고 병사로 모집한 자를 기쁘게 한다고 했다. 
- 바울은 경기하는 자가 규칙대로 하지 않으면 승리자의 관을 얻지 못하며 수고한 자가 곡식을 먼저 받는다고 말한다. 
- 바울은 택함 받은 자들을 위하여 모든 것을 참든데 그리스도 예수 안에서 구원을 영원한 영광과 함께 받도록 하기 위함이라고 했다.
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울은 디모데에게 충성된 사람에게 부탁하여 다른 사람을 가르칠 수 있도록 하라고 권면했는데 지시가 아닌 부탁이라는 단어를 사용한 것을 보면, 복음은 권위적인 것이 아닌 겸손함으로 전해져야 함을 느낄 수 있다.
- 병사로 복무하는 자들은 엄격한 규율을 따르고 자신의 시간이 제한적이며 오직 상관의 지시에 복종하는 자세를 갖는다. 바울이 디모데에게 좋은 병사로 함께 고난을 받으라는 것은 자신을 엄격히 통제하고 가장 낮은 계급으로 사역하길 원한 것으로 보인다. 이 또한 겸손한 자세가 필요하다.
- 바울은 택함 받은 자들을 위해 모든 것을 참는다고 했는데, 신앙 성장의 방점은 오래참음에 있음을 깨닫는다. 인간은 사역을 통해 성과와 결과를 원하는데 성과와 기대, 결과에 미치지 못하는 일들이 너무 많다. 스스로를 괴롭게하고 넘어지게 만드는 시험을 이길 수 있는 방법은 오래참음이다. 한 순간의 화로 그동안 쌓은 성을 쉽게 무너뜨릴 수 있음을 바울은 알고 있었던 것 같다.
9. 적용(나): 
- 겸손한 자세로 주님이 맡기신 사역을 곰곰이 생각해보아야겠다. 내 생각을 버리고 주님 생각이 내 안에 가득 임하기를 소망한다.
10. 영적터치(단어/구절)
- 4 병사로 복무하는 자는 자기 생활에 얽매이는 자가 하나도 없나니 이는 병사로 모집한 자를 기쁘게 하려 함이라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-03-14', '디모데후서', '2장 11절 ~ 20절', '제목 없음', '(디모데후서 2장)
11. 미쁘다 이 말이여 우리가 주와 함께 죽었으면 또한 함께 살 것이요
12. 참으면 또한 함께 왕 노릇 할 것이요 우리가 주를 부인하면 주도 우리를 부인하실 것이라
13. 우리는 미쁨이 없을지라도 주는 항상 미쁘시니 자기를 부인하실 수 없으시리라
14.  너는 그들로 이 일을 기억하게 하여 말다툼을 하지 말라고 하나님 앞에서 엄히 명하라 이는 유익이 하나도 없고 도리어 듣는 자들을 망하게 함이라
15. 너는 진리의 말씀을 옳게 분별하며 부끄러울 것이 없는 일꾼으로 인정된 자로 자신을 하나님 앞에 드리기를 힘쓰라
16. 망령되고 헛된 말을 버리라 그들은 경건하지 아니함에 점점 나아가나니
17. 그들의 말은 악성 종양이 퍼져나감과 같은데 그 중에 후메내오와 빌레도가 있느니라
18. 진리에 관하여는 그들이 그릇되었도다 부활이 이미 지나갔다 함으로 어떤 사람들의 믿음을 무너뜨리느니라
19. 그러나 하나님의 견고한 터는 섰으니 인침이 있어 일렀으되 주께서 자기 백성을 아신다 하며 또 주의 이름을 부르는 자마다 불의에서 떠날지어다 하였느니라
20. 큰 집에는 금 그릇과 은 그릇뿐 아니라 나무 그릇과 질그릇도 있어 귀하게 쓰는 것도 있고 천하게 쓰는 것도 있나니

