7.하나님 찾기 (해석) 

8.인간(해석): 
- 악으로부터 자기를 깨끗하게 하면 귀히 쓰는 그릇이 된다
- 청년의 정욕을 피해야 하고
- 주를 깨끗한 마음으로 부르는 자들과 함께 의와 믿음과 사랑과 화평을 따라야 한다.
- 어리석고 무식한 변론을 버리라. 여기에서 싸움이 난다.
- 주의 종은 마땅히 다투면 안 되며 모든 사람에게 온유하고, 잘 가르치고, 참을성이 있어야 한다.
- 반대자와 다투는 것이 아니라, 온화하게 바로잡아 주어야 하는 것은, 그 반대자를 하나님이 회개시키시고 진리를 깨닫게 하실 것이기 때문이다.
- 반대자들이 마귀에게 사로잡혀 있지만, 
- 하나님이 하시면 마귀의 올무에서 벗어나고 하나님의 뜻을 따를 수 있기 때문이다.

9. 적용(나): 
- 악에서 떠나 나를 깨끗하게 해야 한다.
- 악에서 떠난 다는 것은 성령님의 새롭게 하심으로만 가능한 것이다.
- 오늘도 내일도 성령안에서 말씀을 묵상하고 기도에 힘씀으로 날마다 새롭게 하시는 성령님의 능력 안에서 살아야겠다.
- 그럴 때 마땅히 다투지 아니함과 모든 사람에게 온유함이 따를 것이며,
- 반대자를 저주하지 않고, 
- 주님의 역사하심으로 말미암아 반대자가 회개하고 하나님의 뜻을 따르는자 되기를 위해 기도하는 자가 될 것이다.   

