INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-03-17', '디모데후서', '3장 11절 ~ 17절', '제목 없음', '(디모데후서 3장)
11. 박해를 받음과 고난과 또한 안디옥과 이고니온과 루스드라에서 당한 일과 어떠한 박해를 받은 것을 네가 과연 보고 알았거니와 주께서 이 모든 것 가운데서 나를 건지셨느니라
12. 무릇 그리스도 예수 안에서 경건하게 살고자 하는 자는 박해를 받으리라
13. 악한 사람들과 속이는 자들은 더욱 악하여져서 속이기도 하고 속기도 하나니
14. 그러나 너는 배우고 확신한 일에 거하라 너는 네가 누구에게서 배운 것을 알며
15. 또 어려서부터 성경을 알았나니 성경은 능히 너로 하여금 그리스도 예수 안에 있는 믿음으로 말미암아 구원에 이르는 지혜가 있게 하느니라
16. 모든 성경은 하나님의 감동으로 된 것으로 교훈과 책망과 바르게 함과 의로 교육하기에 유익하니
17. 이는 하나님의 사람으로 온전하게 하며 모든 선한 일을 행할 능력을 갖추게 하려 함이라

