속이는 자
속는 자
박해를 가하는 자
박해를 받는 자
성도는 성경을 통하여 구원에 이르는 지혜가 생김
성경은 믿는자들을 더욱 온전하게 하며 모든 선한 일을 행할 능력을 갖추게 함

7.하나님 찾기 (해석)
하나님은 곧 말씀이시다  하나님의 감동으로 기록된 성경은 모든 사람들 에게 구원에 이르는 복음의 통로이다

믿는 자들에게는 더욱 영적으로 성장시키시며 모든 선한 일을 할수있도록 은혜의 능력을 공급해주신다

8.인간 찾기 (해석)
성경은 하나님이 인간에게 주신 가장 큰 선물일것이다

영 이신 하나님이 오랜시간을 통하여 일관성 있게 쓰신 진리의 말씀을 
인간들에게 사랑의 편지로  주셨다
성경 만으로도 하나님은 인간들과 충분히 소통할수 있는 발판을 만들어 주셨다

그 편지내용은 특히 믿는자들이 이 세상을 어떻게 살아야 할지 방향을 인도 하시는 마치 낟침반 같은 역할을 하고 있다

바울은 성경의 유익 과 능력을 분명히 설명하고 있다 그러한 은혜를 받기 위해서는 날마다 말씀가운데 거하며 교훈 책망 바르게함 과 의 를 더욱 추구해 나갈것을 요청하고 있다

결국 말씀을 날마다 사모하며 깨우침 뉘우침 고침 그리고 행함의 덕목이 따르는 것을 알수있다

9. 적용(나)
더욱 하나님 말씀을 사모하며 3331큐티 도 더욱 깊게 묵상하여 그 능력으로 선하게 살아내는 사람이 되야겠다

