의로운 재판장 되신 주님

6.인간 찾기 (관찰)
항상 복음을 전파하라 권하는 바울
사욕을 따르고 허탄한 이야기를 따르는 사람들
고난을 참고 전도자의 직무를 귄면하는 바울
선한 싸움을 싸우고 끝까지 믿음을 지킨 바울
그런 바울에게 예비된 의의 면류관

7.하나님 찾기 (해석)
세상에는 많은 카르텔과 공정하지 못한 판단과 재판의 결과들이 많이 있다
하지만 마지막때 임하실 재판장 이신 우리 주님은 의로우신 재판장님 이시다

8.인간 찾기 (해석)
겸손한 바울은 천국의 소망을 가지고 있을뿐만 아니라 구원의 확신에 대한 믿음도 겸비하고 있음을 볼수있다

바울의 믿음은 단지 구원을 이루는 믿음 뿐만아니라 이미 천국에서 자신을 위하여 주님께서 준비하신 의의 면류관을 소개하고 있다

세상에서 누구나 경험하는 고난을 당연한 전도자의 직무라고 태연하게 받아들이는 바울의 모습을 알수있다

신앙생활 잘해서 고난을 피해가려고 하는 마음이 아니라 고난을 자신의 선한 싸움의 도구로 이용하는 사도바울의 태도이다

그러한 바울은 자신의 구원과 받을 면류관만을 생각하지 않고 모든 사람들도 이러한 전도자의 길을 가도록 권면하는 주님의 사랑 또한 겸비하고 있다

그는 지금도 하나님의 뜻을 따라 외치고있다
"너는 말씀을 전파하라 때를 얻든지 못 얻든지 항상 힘쓰라"

