INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-03-19', '디모데후서', '4장 11절 ~ 22절', '곁에 서서 힘을 주시는 주님', '디모데후서 4장 11~22절
11   누가만 나와 함께 있느니라 네가 올 때에 마가를 데리고 오라 그가 나의 일에 유익하니라
12   두기고는 에베소로 보내었노라
13   네가 올 때에 내가 드로아 가보의 집에 둔 겉옷을 가지고 오고 또 책은 특별히 가죽 종이에 쓴 것을 가져오라
14   구리 세공업자 알렉산더가 내게 해를 많이 입혔으매 주께서 그 행한 대로 그에게 갚으시리니
15   너도 그를 주의하라 그가 우리 말을 심히 대적하였느니라
16   내가 처음 변명할 때에 나와 함께 한 자가 하나도 없고 다 나를 버렸으나 그들에게 허물을 돌리지 않기를 원하노라
17   주께서 내 곁에 서서 나에게 힘을 주심은 나로 말미암아 선포된 말씀이 온전히 전파되어 모든 이방인이 듣게 하려 하심이니 내가 사자의 입에서 건짐을 받았느니라
18   주께서 나를 모든 악한 일에서 건져내시고 또 그의 천국에 들어가도록 구원하시리니 그에게 영광이 세세무궁토록 있을지어다 아멘
끝 인사
19   브리스가와 아굴라와 및 오네시보로의 집에 문안하라
20   에라스도는 고린도에 머물러 있고 드로비모는 병들어서 밀레도에 두었노니
21   너는 겨울 전에 어서 오라 으불로와 부데와 리노와 글라우디아와 모든 형제가 다 네게 문안하느니라
22   나는 주께서 네 심령에 함께 계시기를 바라노니 은혜가 너희와 함께 있을지어다

