- 자신에 대해 변론할 때 모두가 자신을 버리고 떠났지만, 그들에게 허물을 돌리지 않기를 원하는 바울
- 주께서 자신에게 힘을 주신 이유를 전도의 말씀이 온전히 전파되는 것이라고 말하는 바울
