7.하나님 찾기 (해석) 
- 하나님은 자신 스스로 우리를 구원하시고자 이 땅에 오셔서 자신을 전하는 삶을 스스로 하셨다. 해석할 수 없는 하나님의 사랑이다.
8.인간(해석):
- 바울은 디도에게 리더로 세울 사람들의 기준을 말했는데 대상자를 나로 비교해보자면 나는 리더가 될 수 없는 존재이다. 그만큼 리더는 리더가 가진 영향력과 권위를 의미하는데 리더의 권위는 자신을 드러내고 스스로 높아지는데 사용되는 권위가 아니라 성도들을 섬기고 성도들의 연약한 부분을 책망할 수 있는 데에 사용할 수 있는 권위를 뜻한다. 
- 리더가 바로서야 리더를 따르는 사람들이 리더를 존중하고 존경할 수 있다. 하지만 자리만 차지하는 영향력 없는 리더는 리더를 따르는 사람들에게 리더의 영향력과 권위에 대한 시험에 들게하는 존재가 될 수 있다. 그렇기에 바울은 리더의 기준을 높게 잡은 것 같다. 
9. 적용(나): 
- 리더로 설 수 없는 존재이지만 하나님의 은혜로 NKFC의 리더로 섬길 수 있는 기회가 주어졌다. 이것은 당연한 것이 아닌 하나님의 은혜이기 때문에 이 자리를 허락하심에 감사해야겠다. 
- NKFC 회원들의 내 모습에 실망하지 않도록 굳건해야겠다. 
