4.주제 만들기: 그리스도인에게 주는 교훈

5.하나님 찾기 (관찰)

6.인간 찾기 (관찰)
- 늙은 남자, 늙은 여자, 젊은 여자, 젊은 남자, 종에게 줄 교훈에 대해 말하는 바울
- 디도에게 교훈을 주는 바울 

7.하나님 찾기 (해석) 

8.인간(해석)
- 늙은 남자는 절제 하고, 위엄을 갖추고, 신중하며, 믿음과 사랑과 인내에 있어서 건전한 사람이 되어야 한다.
- 늙은 여자는 행실이 거룩하고, 헐뜯지 말고, 술의 노예가 되지 않도록 하고 좋은 것을 가츠시는 사람이 되어야 한다.
- 늙은 여자는 젊은 여자를 깨우쳐 남편과 자녀를 사랑하며, 신중하며, 순결하며, 집안 살림을 잘 하며, 선하며, 남편에게 순종하는 사람이 되게 해야 한다.
- 젊은 남자는 신중해야한다.
- 목회자(또는 가르치는 사람)는 자신이 가르친 모든 점에서 선한 행실의 모범이 돼야 한다.
- 목회자는 가르치는 일에 순수하고 위엄이 있어야 한다.
- 책잡힐 데가 없는 건전한 말을 해야 한다. 
- 이런 것들이 이루어져야 대적자가 우리를 공격하고자 할 때 나쁘게 말할 것이 없어 부끄러움을 당할 것이다.
- 종은 모든 일에 자기 주인에게 복종하며, 기쁘게 하며 말대꾸를 하지 말며, 훔치지 말며, 온전히 신실한 사람이 되게 가르쳐야 한다.
- 그렇게 할 때 모든 일에 하나님의 교훈이 빛나게 될 것이다.

9.적용(나) 
- 늙은 남자부터 종에게 준 모든 교훈을 내게 주어지는 교훈으로 여기고 따르고자 노력해야 겠다.
- 내가 가르친 모든 점에서 선한 행실의 모범이 되고,
- 가르칠 때는 순수하고 위엄이 있는 모습으로 해야 하며,
- 책잡힐 데가 없는 건전한 말을 해야 한다.
- 이런 것들은 모두, 오직 성령님의 능력으로만 할 수 있는 것들이기에 기도에 힘써야겠다.


