4.주제만들기: 선한 일을 열심히 할 수 있는 은혜 
5.하나님 찾기 (관찰)
- 구원을 주시고 하나님의 은혜로 우리를 양육하심
- 경건하지 않은 것과 세상 정욕을 버리게 하시고, 신중함과 의로움과 경건함으로 이 세상에 살 수 있게 하심
- 복스러운 소망과 하나님의 영광이 나타나심을 기다리게 하심
- 우리를 대신하여 자신을 주셨고 모든 불법에서 속량하셨으며 우리를 깨끗게하여 선한 일을 열심히 하는 자기 백성이 되게 하심
6.인간 찾기 (관찰)
- 바울은 이러한 사실을 전하고 권위를 활용하여 책망하므로 업신 여김을 당하지 말라고 말하였다. 
7.하나님 찾기 (해석) 
- 우리에게 구원을 주셨는데, 구원만으로 인간은 완전해 질 수 없기 때문에 우리는 하나님의 은혜로 하나님께 양육을 받을 수 있다. 경건하지 않은 것, 대표적으로 세상 정욕을 버릴 수 있는 용기과 결단은 전적으로 하나님의 은혜이다. 이를 통해 신중함과 의로움으로 세상을 살아갈 수 있는데 모든 일에 신중해야 한다는 것은 의로운 길을 선택할 수 있는 지혜가 더하여 지는 것이고, 의로운 길을 반복적으로 선택하면 경건을 유지할 수 있게 된다. 
8.인간(해석):
- 바울은 경건의 단계에 이른 리더는 귄위를 가질 수 있으므로 이를 바탕으로 경건치 못한 성도들에게 과감히 책망하도록 권면했다. 권위가 없는 상태라면 책망치 못했을 것이다. 디도가 어떤 리더였는지 깨닫게 된다.
9. 적용(나): 
- 세상에서의 전도, 구제 등의 소명을 분명하지만, 세상에서의 나의 삶은 경건을 향해 나아가야 한다. 세상 정욕을 끊고, 신중함과 의로움과 경건함이 내안에 가득 임하길 기도한다.
10. 영적터치(단어/구절): 경건
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

INSERT INTO qts (date, book, chapter, title, content, views, is_public) VALUES ('2024-03-25', '디도서', '3장 1절 ~ 10절', '제목 없음', '(디도서 3장)
1. 너는 그들로 하여금 통치자들과 권세 잡은 자들에게 복종하며 순종하며 모든 선한 일 행하기를 준비하게 하며
2. 아무도 비방하지 말며 다투지 말며 관용하며 범사에 온유함을 모든 사람에게 나타낼 것을 기억하게 하라
3. 우리도 전에는 어리석은 자요 순종하지 아니한 자요 속은 자요 여러 가지 정욕과 행락에 종 노릇 한 자요 악독과 투기를 일삼은 자요 가증스러운 자요 피차 미워한 자였으나
4. 우리 구주 하나님의 자비와 사람 사랑하심이 나타날 때에
5. 우리를 구원하시되 우리가 행한 바 의로운 행위로 말미암지 아니하고 오직 그의 긍휼하심을 따라 중생의 씻음과 성령의 새롭게 하심으로 하셨나니
6. 우리 구주 예수 그리스도로 말미암아 우리에게 그 성령을 풍성히 부어 주사
7. 우리로 그의 은혜를 힘입어 의롭다 하심을 얻어 영생의 소망을 따라 상속자가 되게 하려 하심이라
8. 이 말이 미쁘도다 원하건대 너는 이 여러 것에 대하여 굳세게 말하라 이는 하나님을 믿는 자들로 하여금 조심하여 선한 일을 힘쓰게 하려 함이라 이것은 아름다우며 사람들에게 유익하니라
9. 그러나 어리석은 변론과 족보 이야기와 분쟁과 율법에 대한 다툼은 피하라 이것은 무익한 것이요 헛된 것이니라
10. 이단에 속한 사람을 한두 번 훈계한 후에 멀리하라

