6.인간 찾기 (관찰)
- 빌레몬과 교회에 안부 인사하는 바울
- 빌레몬으로 인해 감사하며 하나님께 기도하는 바울
- 빌레몬의 믿음과 교회에 대한 사랑에 대해 말하는 바울
- 빌레몬에게 오네시모를 두고 간절히 부탁하는 바울

7.하나님 찾기 (해석) 

8.인간(해석): 
- 믿음의 동역자가 믿음 생활을 잘하는 것으로 하나님께 감사하는 바울
- 빌레몬의 믿음과 성도를 향한 사랑이 자신의 기쁨이 되는 바울
- 빌레몬과 주 안에서 이루어지는 믿음의 사귐을 기뻐하고
- 빌레몬이 그리스도께 가까이 나아갈 때 얻는 복에 대해 알기 원함.
- 바울은 교회의 어른이고 복음을 위하여 감옥에 갇힌 자로서 그의 지위로 명령할 수 있지만
- 명령하지 않고 빌레몬에게 정중히 그리고 간절하게 부탁한다.

9. 적용(나): 
- 주님을 믿는 믿음 안에서 이루어지는 성도의 교제의 중요성에 대해 생각해 본다.
- 성도의 교제를 지속할 수 있도록, 공동체를 더욱 사랑하도록 노력해야 한다.
