4.주제만들기: 자유케 하려는 바울의 권면
5.하나님 찾기 (관찰)
6.인간 찾기 (관찰)
- 빌레몬에게 오네시모를 돌려보내는 바울
- 빌레몬으로부터 오네시모를 보호해주는 바울
- 오네시모를 용서해달라는 바울의 권면
7.하나님 찾기 (해석) 
8.인간(해석):
- 바울은 빌레몬에게 편지를 하며 오네시모를 돌려보내는 이유에 대해 말했다. 무슨 이유에서인지는 모르겠으나 오네시모는 빌레몬의 종이고 주인을 벗어난 종을 주인에게 돌려보낸다는 것은 일반적인 기준에선 죽음을 뜻할 수도 있다. 
- 그러나 바울은 빌레몬에게 권면한다. 빌레몬에게 권면할 수 있었던 이유는 빌레몬이 신앙 생활을 잘했던 성도였기 때문일 것이다. 빌레몬에게 오네시모를 돌려보냄으로서 빌레몬은 용서를 통한 자유함을 얻게하고 오네시모는 주인을 벗어난 죄책감을 털어버릴 수 있는 기회가 될 것이다. 
- 더불어 바울은 당시 시대의 종에 대해 언급하였는데 예수님을 만난 인간은 같은 인간을 종으로 두어서는 안 된다. 바울은 빌레몬을 자신의 심복이라 표현하며 감쌌는데 신앙 생활을 잘하고 있는 빌레몬이기에 사랑으로 품을 수 있을 것이라 판단했던 것 같다. 
9. 적용(나): 
- 내 자신이 누구보다 우월하거나 잘났다고 생각하는 교만이 나에게 없길 바란다. 
- 선교, 구제, 전도 등을 할 때 하나님을 믿는 믿음이 교만이 되어 스스로 높아지는 자만이 생기지 않도록 주의해야겠다. 특히 가난한 영혼을 만날 때 더 주의해야겠다. 
- 모든 영혼을 진심으로 사랑하고 예수님을 알지 못하는 안타까움이 내 안에 가득하기 기도해야겠다.
10. 영적터치(단어/구절):
- 20 오 형제여 나로 주 안에서 너로 말미암아 기쁨을 얻게 하고 내 마음이 그리스도 안에서 평안하게 하라
11. 믿음과 회개 및 감사기도로 마무리
12.받은 은혜의 말씀 24시간 묵상하며 주님과 동행하기', 0, true);

